import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key chưa được cấu hình.");
  }
  return new GoogleGenAI({ apiKey });
};

export const decodeImagePrompt = async (base64Data: string, mimeType: string): Promise<AnalysisResult> => {
  try {
    const ai = getClient();

    const imagePart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Data
      }
    };

    const promptText = `
      Đóng vai một chuyên gia hàng đầu về Reverse Prompt Engineering cho Generative AI (Midjourney, Stable Diffusion, DALL-E 3). Nhiệm vụ của bạn là giải mã hình ảnh này thành một prompt văn bản có độ chính xác cao nhất để tái tạo lại nó.

      Hãy phân tích sâu các yếu tố sau:
      1.  **Medium & Style (Chất liệu & Phong cách):** Đây là ảnh chụp (photography), 3D render, tranh sơn dầu, digital art, anime hay vector? Phong cách cụ thể là gì (Cyberpunk, Baroque, Minimalism, Photorealistic...)?
      2.  **Subject (Chủ thể):** Mô tả cực kỳ chi tiết về chủ thể chính (quần áo, chất liệu vải, biểu cảm, tư thế, đặc điểm khuôn mặt).
      3.  **Environment & Composition (Bối cảnh & Bố cục):** Hậu cảnh, các chi tiết phụ, góc máy (low angle, wide shot, macro), độ sâu trường ảnh (bokeh, sharp focus).
      4.  **Lighting & Color (Ánh sáng & Màu sắc):** Loại ánh sáng (cinematic lighting, volumetric, rim light, natural light), hướng sáng, bảng màu chủ đạo (warm tones, cool palette, pastel).
      5.  **Aspect Ratio (Tỷ lệ khung hình):** Quan sát kích thước ảnh để xác định tỷ lệ khung hình chính xác (ví dụ: 1:1, 16:9, 9:16, 4:3, 3:2...).
      6.  **Quality Keywords (Từ khóa chất lượng):** Các từ khóa kỹ thuật giúp tăng độ nét và chi tiết (8k resolution, unreal engine 5, masterpiece, intricate details).

      Yêu cầu Output JSON:
      - "prompt": Tạo một prompt hoàn chỉnh. **BẮT BUỘC** phải bắt đầu bằng chính xác đoạn văn bản tiếng Anh sau: "Create a highly realistic studio portrait of the woman from the uploaded photo, ensuring her face is 99.99% identical to the reference. Use the face and body from the reference image exactly, keeping the same proportions and hairstyle." Sau đó nối tiếp bằng mô tả chi tiết các yếu tố hình ảnh (trang phục, biểu cảm, bối cảnh, ánh sáng, phong cách...) bằng **TIẾNG ANH** để tạo thành một prompt thống nhất. Cuối cùng là tham số tỷ lệ khung hình (ví dụ: --ar 16:9) dựa trên phân tích hình ảnh.
      - "suggestions": Danh sách 3-5 gợi ý kỹ thuật cụ thể bằng TIẾNG VIỆT để người dùng tinh chỉnh kết quả sát với ảnh gốc nhất (ví dụ: gợi ý về Negative Prompt, phiên bản model --v 6.0, hoặc tên Artist cụ thể nên dùng).

      Đảm bảo JSON hợp lệ.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [imagePart, { text: promptText }]
      },
      config: {
        temperature: 0.3, // Lower temperature for more precise/determinstic analysis
        topK: 32,
        topP: 0.8,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prompt: {
              type: Type.STRING,
            },
            suggestions: {
              type: Type.ARRAY,
              items: {
                type: Type.STRING
              }
            }
          },
          required: ["prompt", "suggestions"]
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("Không nhận được phản hồi từ AI.");
    }

    return JSON.parse(text) as AnalysisResult;
  } catch (error: any) {
    console.error("Lỗi khi gọi Gemini API:", error);
    throw new Error(error.message || "Đã xảy ra lỗi khi phân tích hình ảnh.");
  }
};

