              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
            </svg>
          </div>

          <h3 className="text-2xl font-bold text-gray-800 mb-3">Tải ảnh lên</h3>
          <p className="text-gray-500 text-base max-w-sm mx-auto leading-relaxed">
            Kéo thả, <span className="text-purple-600 font-semibold">dán (Ctrl+V)</span> hình ảnh vào đây hoặc nhấp (Enter) để chọn từ thư viện
          </p>

          <div className="mt-8 flex gap-3 text-xs font-semibold text-gray-400 uppercase tracking-wide">
            <span className="bg-gray-100 px-3 py-1 rounded-full">JPG</span>
            <span className="bg-gray-100 px-3 py-1 rounded-full">PNG</span>
            <span className="bg-gray-100 px-3 py-1 rounded-full">WEBP</span>
          </div>
        </>
      )}
    </div>
  );
};

export interface AnalysisResult {
  prompts: string[];
  suggestions: string[];
}

export interface ImageFile {
  file: File;
  previewUrl: string;
  base64: string;
  mimeType: string;
}

export enum AppState {
  IDLE = 'IDLE',
  ANALYZING = 'ANALYZING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key chưa được cấu hình.");
  }
  return new GoogleGenAI({ apiKey });
};

export const decodeImagePrompt = async (base64Data: string, mimeType: string, count: number = 1): Promise<AnalysisResult> => {
  try {
    const ai = getClient();

    const imagePart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Data
      }
    };

    const promptText = `
      Đóng vai một chuyên gia hàng đầu về Reverse Prompt Engineering cho Generative AI (Midjourney, Stable Diffusion, DALL-E 3). Nhiệm vụ của bạn là giải mã hình ảnh này và tạo ra ${count} prompt(s).

      Hãy phân tích sâu các yếu tố sau:
      1.  **Medium & Style:** Chất liệu, phong cách nghệ thuật (Cyberpunk, Baroque, Photorealistic...).
      2.  **Subject:** Mô tả chủ thể. Nếu ảnh có nhiều khuôn mặt/góc độ, hãy coi là CÙNG MỘT NGƯỜI.
      3.  **Environment, Lighting, Quality:** Bối cảnh, ánh sáng, từ khóa chất lượng (8k, masterpiece...).

      Yêu cầu Output JSON:
      - "prompts": Một mảng chứa đúng ${count} chuỗi văn bản (strings).
        *   Prompt đầu tiên (Index 0): Phải là prompt chính xác nhất để tái tạo ảnh gốc. Bắt buộc bắt đầu bằng: "Create a highly realistic studio portrait of the subject from the uploaded photo. Even if the reference image displays multiple faces or angles, they represent the same person; ensure the generated face is 99.99% identical to this reference identity. Use the face and body features from the reference exactly, preserving proportions and hairstyle." sau đó nối tiếp bằng mô tả chi tiết tiếng Anh.
        *   Các prompt tiếp theo (nếu có): Là các biến thể sáng tạo dựa trên Prompt đầu tiên. Giữ nguyên phong cách (Style), chất liệu (Medium) và đặc điểm nhận dạng của chủ thể, nhưng thay đổi nhẹ về bối cảnh, tư thế, hoặc trang phục để tạo ra sự đa dạng.
      - "suggestions": Danh sách 3-5 gợi ý kỹ thuật cụ thể bằng TIẾNG VIỆT.

      Đảm bảo JSON hợp lệ.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [imagePart, { text: promptText }]
      },
      config: {
        temperature: 0.4, 
        topK: 32,
        topP: 0.8,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prompts: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            suggestions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["prompts", "suggestions"]
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("Không nhận được phản hồi từ AI.");
    }

    return JSON.parse(text) as AnalysisResult;
  } catch (error: any) {
    console.error("Lỗi khi gọi Gemini API:", error);
    throw new Error(error.message || "Đã xảy ra lỗi khi phân tích hình ảnh.");
  }
};

import React, { useState } from 'react';

interface PromptDisplayProps {
  prompts: string[];
