import React, { useRef, useState, useEffect } from 'react';
import { ImageFile } from '../types';

interface ImageUploaderProps {
  onImageSelected: (image: ImageFile) => void;
  disabled?: boolean;
}

export const ImageUploader: React.FC<ImageUploaderProps> = ({ onImageSelected, disabled }) => {
  const [isDragging, setIsDragging] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    if (!disabled) setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const compressImage = (file: File): Promise<{ base64: string, preview: string, mimeType: string }> => {
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const MAX_DIMENSION = 1536; // Resize to max 1536px to optimize API speed

          if (width > height) {
            if (width > MAX_DIMENSION) {
              height *= MAX_DIMENSION / width;
              width = MAX_DIMENSION;
            }
          } else {
            if (height > MAX_DIMENSION) {
              width *= MAX_DIMENSION / height;
              height = MAX_DIMENSION;
            }
          }

          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          ctx?.drawImage(img, 0, 0, width, height);

          // Always convert to JPEG with 0.85 quality for optimal balance
          const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
          const base64 = dataUrl.split(',')[1];

          resolve({
            base64,
            preview: dataUrl,
            mimeType: 'image/jpeg'
          });
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const processFile = async (file: File) => {
    if (!file.type.startsWith('image/')) {
      alert('Vui lòng chọn tệp hình ảnh hợp lệ.');
      return;
    }

    setIsProcessing(true);
    try {
      const { base64, preview, mimeType } = await compressImage(file);
      onImageSelected({
        file,
        previewUrl: preview,
        base64,
        mimeType
      });
    } catch (error) {
      console.error("Error processing image", error);
      alert("Có lỗi khi xử lý hình ảnh.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handlePasteClick = async (e: React.MouseEvent) => {
    e.stopPropagation(); // Stop bubbling to parent which triggers file input
    if (disabled || isProcessing) return;

    try {
      // Check if the Clipboard API is supported
      if (!navigator.clipboard || !navigator.clipboard.read) {
        alert("Trình duyệt của bạn không hỗ trợ nút dán này (yêu cầu kết nối an toàn HTTPS hoặc localhost). Vui lòng sử dụng phím tắt Ctrl+V.");
        return;
      }

      const clipboardItems = await navigator.clipboard.read();
      let found = false;

      for (const item of clipboardItems) {
        // Prioritize finding an image type
        const imageType = item.types.find(type => type.startsWith('image/'));
        if (imageType) {
          const blob = await item.getType(imageType);
          const file = new File([blob], "pasted_image", { type: imageType });
          processFile(file);
          found = true;
          break;
        }
      }

      if (!found) {
        alert("Không tìm thấy hình ảnh nào trong bộ nhớ tạm (Clipboard).");
      }
    } catch (error) {
      console.error("Paste error:", error);
      // Often permission denied or not focused
      alert("Không thể dán ảnh. Vui lòng cấp quyền truy cập bộ nhớ tạm hoặc sử dụng phím tắt Ctrl+V.");
    }
  };

  // Handle global paste event
  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      if (disabled || isProcessing) return;

      const items = e.clipboardData?.items;
      if (!items) return;

      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const file = items[i].getAsFile();
          if (file) {
            e.preventDefault();
            processFile(file);
            return;
          }
        }
      }
    };

    document.addEventListener('paste', handlePaste);
    return () => {
      document.removeEventListener('paste', handlePaste);
    };
  });

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (disabled || isProcessing) return;

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      processFile(e.target.files[0]);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (disabled || isProcessing) return;
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      fileInputRef.current?.click();
    }
  };

  return (
    <div
      role="button"
      tabIndex={disabled ? -1 : 0}
      aria-label="Tải ảnh lên"
      onKeyDown={handleKeyDown}
      className={`relative group cursor-pointer transition-all duration-300 ease-out border-3 border-dashed rounded-[2rem] p-10 flex flex-col items-center justify-center text-center bg-white shadow-sm hover:shadow-xl focus:outline-none focus:ring-4 focus:ring-purple-200
        ${isDragging ? 'border-purple-500 bg-purple-50 scale-[1.01] shadow-xl' : 'border-gray-300 hover:border-purple-400'}
        ${disabled || isProcessing ? 'opacity-50 cursor-not-allowed pointer-events-none' : ''}
      `}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      onClick={() => fileInputRef.current?.click()}
    >
      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileChange}
        accept="image/*"
        className="hidden"
        disabled={disabled || isProcessing}
      />

      {isProcessing ? (
        <div className="flex flex-col items-center">
           <div className="w-12 h-12 border-4 border-purple-200 border-t-purple-600 rounded-full animate-spin mb-4"></div>
           <p className="text-purple-600 font-medium">Đang tối ưu hóa ảnh...</p>
        </div>
      ) : (
        <>
          <div className="w-24 h-24 mb-6 bg-purple-50 text-purple-600 rounded-full flex items-center justify-center transition-transform duration-300 group-hover:scale-110 group-hover:bg-purple-100 shadow-inner">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
            </svg>
          </div>

          <h3 className="text-2xl font-bold text-gray-800 mb-3">Tải ảnh lên</h3>
          <p className="text-gray-500 text-base max-w-sm mx-auto leading-relaxed mb-6">
            Kéo thả hoặc nhấp để chọn ảnh
          </p>

          <button
            type="button"
            onClick={handlePasteClick}
            className="relative z-10 mb-8 flex items-center gap-2 px-5 py-2.5 bg-white text-gray-700 font-semibold rounded-xl border border-gray-200 shadow-sm hover:bg-purple-50 hover:text-purple-700 hover:border-purple-200 hover:shadow-md transition-all duration-200 group/btn"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-gray-400 group-hover/btn:text-purple-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
            </svg>
            <span>Dán ảnh từ Clipboard</span>
          </button>

          <div className="flex gap-3 text-xs font-semibold text-gray-400 uppercase tracking-wide">
            <span className="bg-gray-100 px-3 py-1 rounded-full">JPG</span>
            <span className="bg-gray-100 px-3 py-1 rounded-full">PNG</span>
            <span className="bg-gray-100 px-3 py-1 rounded-full">WEBP</span>
          </div>
        </>
      )}
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key chưa được cấu hình.");
  }
  return new GoogleGenAI({ apiKey });
};

export const decodeImagePrompt = async (base64Data: string, mimeType: string, count: number = 1): Promise<AnalysisResult> => {
  try {
    const ai = getClient();

    const imagePart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Data
      }
    };

    const promptText = `
      Đóng vai một chuyên gia hàng đầu về Reverse Prompt Engineering cho Generative AI (Midjourney, Stable Diffusion, DALL-E 3). Nhiệm vụ của bạn là giải mã hình ảnh này và tạo ra ${count} prompt(s).

      Hãy phân tích sâu các yếu tố sau:
      1.  **Medium & Style:** Chất liệu, phong cách nghệ thuật (Cyberpunk, Baroque, Photorealistic...).
      2.  **Subject:** Mô tả chủ thể. Nếu ảnh có nhiều khuôn mặt/góc độ, hãy coi là CÙNG MỘT NGƯỜI.
      3.  **Environment, Lighting, Quality:** Bối cảnh, ánh sáng, từ khóa chất lượng (8k, masterpiece...).

      Yêu cầu Output JSON:
      - "prompts": Một mảng chứa đúng ${count} chuỗi văn bản (strings).
        *   Prompt đầu tiên (Index 0): Phải là prompt chính xác nhất để tái tạo ảnh gốc. Bắt buộc bắt đầu bằng: "Create a highly realistic studio portrait of the subject from the uploaded photo. Even if the reference image displays multiple faces or angles, they represent the same person; ensure the generated face is 99.99% identical to this reference identity. Focus strictly on preserving facial features exactly; hairstyle can be changed or adapted." sau đó nối tiếp bằng mô tả chi tiết tiếng Anh.
        *   Các prompt tiếp theo (từ Index 1 trở đi): BẮT BUỘC phải thay đổi rõ rệt về **Góc máy (Camera Angle)** và **Tư thế (Pose)** để tạo sự đa dạng tối đa.
            - Không được lặp lại bố cục của ảnh gốc.
            - Ví dụ: Nếu ảnh gốc là chân dung (Portrait), hãy tạo biến thể toàn thân (Full body shot) đang di chuyển. Hoặc góc chụp từ dưới lên (Low angle), góc rộng (Wide angle), góc nghiêng thần thánh (Side profile).
            - Đảm bảo mỗi biến thể mang một cảm xúc dáng vẻ khác nhau nhưng VẪN GIỮ NGUYÊN đặc điểm nhận dạng khuôn mặt của chủ thể (Face Identity). Kiểu tóc có thể thay đổi linh hoạt.
      - "suggestions": Danh sách 3-5 gợi ý kỹ thuật cụ thể bằng TIẾNG VIỆT để cải thiện ảnh này tốt hơn.

      Đảm bảo JSON hợp lệ.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [imagePart, { text: promptText }]
      },
      config: {
        temperature: 0.5, // Tăng nhẹ temperature để các biến thể sáng tạo hơn về dáng
        topK: 32,
        topP: 0.9,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prompts: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            suggestions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["prompts", "suggestions"]
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("Không nhận được phản hồi từ AI.");
    }

    return JSON.parse(text) as AnalysisResult;
  } catch (error: any) {
    console.error("Lỗi khi gọi Gemini API:", error);
    throw new Error(error.message || "Đã xảy ra lỗi khi phân tích hình ảnh.");
  }
};

