import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key chưa được cấu hình trong hệ thống. Vui lòng kiểm tra biến môi trường.");
  }
  return new GoogleGenAI({ apiKey });
};

export const decodeImagePrompt = async (base64Data: string, mimeType: string, count: number = 1): Promise<AnalysisResult> => {
  try {
    const ai = getClient();

    const imagePart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Data
      }
    };

    const promptText = `
      Đóng vai một chuyên gia hàng đầu về Reverse Prompt Engineering và Nhà Thiết Kế Thời Trang Kỹ Thuật (Technical Fashion Designer). Nhiệm vụ tối thượng của bạn là giải mã hình ảnh này để **tái tạo lại chính xác trang phục (Outfit)** trong ảnh.

      Hãy thực hiện "Phẫu thuật thời trang" (Fashion Autopsy) cực kỳ chi tiết các yếu tố sau:

      1.  **PHÂN TÍCH TRANG PHỤC (CRITICAL - CHI TIẾT TUYỆT ĐỐI):**
          - **Chất liệu (Fabrication):** Đừng chỉ nói chung chung. Hãy xác định chính xác: Lụa (Satin, Charmeuse, Chiffon?), Len (Cable knit, Cashmere, Ribbed?), Da (Patent leather, Suede, Matte?), Denim (Washed, Raw?), Ren (Lace, Guipure?). Mô tả độ dày, độ rủ, độ bóng và bề mặt vải (texture).
          - **Kiểu dáng (Silhouette & Cut):** Oversized, Bodycon, A-line, Asymmetrical (bất đối xứng), Drape (xếp nếp), Corset structure?
          - **Chi tiết thiết kế (Garment Details):** Cổ áo (Halter, Cowl neck, Sweetheart...), Tay áo (Puff, Raglan, Off-shoulder...), Chi tiết đính kết (Sequins, Embroidery, Ruffles, Feathers).
          - **Màu sắc & Họa tiết:** Gọi tên màu cụ thể (ví dụ: "Emerald Green" thay vì "Green", "Pastel Pink" thay vì "Pink") và mô tả họa tiết in ấn chính xác.

      2.  **Chi tiết Ngoại hình (Character):** 
          - **Kiểu tóc (Exact Hairstyle):** Màu sắc, độ dài, texture (xoăn sóng nước, duỗi thẳng, búi lơi), ngôi tóc.
          - **Phụ kiện:** Khuyên tai, vòng cổ (chunky chain, pearls), kính mắt, thắt lưng, túi xách.

      3.  **Nhiếp ảnh & Ánh sáng:**
          - Loại ánh sáng (Rembrandt, Butterfly, Natural window light, Neon), góc máy và loại film/camera (nếu có).

      Yêu cầu Output JSON:
      - "prompts": Một mảng chứa đúng ${count} chuỗi văn bản (strings).
        *   **Prompt Index 0 (Bản sao hoàn hảo - Replica):** 
            - Đây là prompt quan trọng nhất. Hãy dành 60-70% dung lượng prompt để mô tả **TRANG PHỤC**.
            - Cấu trúc: "Professional fashion photography of [Subject] wearing [CỰC KỲ CHI TIẾT VỀ TRANG PHỤC + CHẤT LIỆU + MÀU SẮC + KIỂU DÁNG], [Chi tiết tóc & Phụ kiện], [Pose], [Background], [Lighting & Camera keywords]".
            - Sử dụng từ vựng thời trang tiếng Anh chuyên ngành (ví dụ: "intricate lace detailing", "sheer organza overlay", "high-gloss latex").
        *   **Prompt Index 1 trở đi (Biến thể Lookbook):** 
            - **BẮT BUỘC GIỮ NGUYÊN:** Toàn bộ mô tả về Trang phục, Chất liệu và Đặc điểm khuôn mặt của Prompt 0.
            - **THAY ĐỔI:** Góc chụp (Close-up, Full body shot, Low angle), Bối cảnh (Background) hoặc Ánh sáng để tạo ra sự đa dạng cho bộ ảnh.
      - "suggestions": Danh sách 3-5 gợi ý kỹ thuật bằng TIẾNG VIỆT để người dùng tinh chỉnh nếu ảnh tạo ra chưa giống (ví dụ: đề xuất thêm từ khóa về loại vải cụ thể, hoặc tên loại ánh sáng).

      Đảm bảo JSON hợp lệ.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [imagePart, { text: promptText }]
      },
      config: {
        temperature: 0.3, 
        topK: 32,
        topP: 0.8,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prompts: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            suggestions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["prompts", "suggestions"]
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("AI không trả về nội dung nào. Có thể ảnh quá phức tạp hoặc bị hệ thống lọc chặn.");
    }

    try {
      return JSON.parse(text) as AnalysisResult;
    } catch (e) {
      throw new Error("Lỗi định dạng dữ liệu từ AI. Vui lòng thử lại.");
    }

  } catch (error: any) {
    console.error("Lỗi khi gọi Gemini API:", error);

    // Categorize errors for better user feedback
    const msg = error.message || "";

    if (msg.includes("API_KEY") || msg.includes("400")) {
      throw new Error("Khóa API không hợp lệ hoặc đã hết hạn. Vui lòng kiểm tra cấu hình.");
    }

    if (msg.includes("SAFETY") || msg.includes("blocked") || msg.includes("finishReason")) {
      throw new Error("Hình ảnh bị hệ thống an toàn chặn. Vui lòng thử ảnh khác ít nhạy cảm hơn (tránh ảnh hở hang, bạo lực...).");
    }

    if (msg.includes("429") || msg.includes("Quota") || msg.includes("resource exhausted")) {
      throw new Error("Hệ thống đang quá tải hoặc hết hạn ngạch (Quota). Vui lòng đợi 1 phút và thử lại.");
    }

    if (msg.includes("500") || msg.includes("503") || msg.includes("Failed to fetch")) {
      throw new Error("Lỗi kết nối mạng hoặc máy chủ Google đang bảo trì. Vui lòng kiểm tra internet và thử lại.");
    }

    throw new Error(msg || "Đã xảy ra lỗi không xác định khi phân tích hình ảnh.");
  }
};

import React, { useRef, useState, useEffect } from 'react';
import { ImageFile } from '../types';

interface ImageUploaderProps {
  onImageSelected: (image: ImageFile) => void;
  onError: (message: string) => void;
  disabled?: boolean;
}

// Worker code as a string to avoid bundler configuration issues
const WORKER_CODE = `
  self.onmessage = async (e) => {
    const { file, maxDimension = 1536, quality = 0.85 } = e.data;

    try {
      // Create bitmap from file (efficient and off-main-thread compatible)
      const bitmap = await createImageBitmap(file);
      let width = bitmap.width;
      let height = bitmap.height;

      // Calculate new dimensions
      if (width > height) {
        if (width > maxDimension) {
          height *= maxDimension / width;
          width = maxDimension;
        }
      } else {
        if (height > maxDimension) {
          width *= maxDimension / height;
          height = maxDimension;
        }
      }

      // Use OffscreenCanvas for resize/compression
      const offscreen = new OffscreenCanvas(width, height);
      const ctx = offscreen.getContext('2d');
      ctx.drawImage(bitmap, 0, 0, width, height);

      // Convert to blob
      const blob = await offscreen.convertToBlob({ 
        type: 'image/jpeg', 
        quality 
      });

      // Convert blob to Data URL for preview and base64 extraction
      const reader = new FileReader();
      reader.onloadend = () => {
        const dataUrl = reader.result;
        // Basic validation
        if (typeof dataUrl === 'string') {
            const base64 = dataUrl.split(',')[1];
            self.postMessage({ 
                success: true, 
                base64, 
                preview: dataUrl, 
                mimeType: 'image/jpeg' 
            });
        } else {
            self.postMessage({ success: false, error: 'Lỗi chuyển đổi dữ liệu ảnh.' });
        }
      };
      reader.onerror = () => {
        self.postMessage({ success: false, error: 'Không thể đọc dữ liệu file.' });
      };
      reader.readAsDataURL(blob);

    } catch (error) {
      self.postMessage({ success: false, error: error.message || 'Lỗi xử lý ảnh trong Worker.' });
    }
  };
`;

export const ImageUploader: React.FC<ImageUploaderProps> = ({ onImageSelected, onError, disabled }) => {
  const [isDragging, setIsDragging] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    if (!disabled) setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  // Fallback compression for browsers without OffscreenCanvas support in Workers
  const compressImageFallback = (file: File): Promise<{ base64: string, preview: string, mimeType: string }> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onerror = () => reject(new Error("File ảnh bị lỗi hoặc không hỗ trợ."));
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const MAX_DIMENSION = 1536;

          if (width > height) {
            if (width > MAX_DIMENSION) {
              height *= MAX_DIMENSION / width;
              width = MAX_DIMENSION;
            }
          } else {
            if (height > MAX_DIMENSION) {
              width *= MAX_DIMENSION / height;
              height = MAX_DIMENSION;
            }
          }

          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) {
            reject(new Error("Trình duyệt không hỗ trợ Canvas 2D."));
            return;
          }
          ctx.drawImage(img, 0, 0, width, height);

          const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
          const base64 = dataUrl.split(',')[1];

          resolve({
            base64,
            preview: dataUrl,
            mimeType: 'image/jpeg'
          });
        };
        img.src = event.target?.result as string;
      };
      reader.onerror = () => reject(new Error("Không thể đọc file."));
      reader.readAsDataURL(file);
    });
  };

  const compressImageWithWorker = (file: File): Promise<{ base64: string, preview: string, mimeType: string }> => {
    return new Promise((resolve, reject) => {
      // Check if OffscreenCanvas is supported in this browser environment
      if (!('OffscreenCanvas' in window)) {
        console.warn('OffscreenCanvas not supported, falling back to main thread.');
        compressImageFallback(file).then(resolve).catch(reject);
        return;
      }

      try {
        const blob = new Blob([WORKER_CODE], { type: 'application/javascript' });
        const worker = new Worker(URL.createObjectURL(blob));

        worker.onmessage = (e) => {
          const { success, base64, preview, mimeType, error } = e.data;
          worker.terminate(); // Clean up

          if (success) {
            resolve({ base64, preview, mimeType });
          } else {
            // If worker fails, try fallback
            console.warn('Worker failed:', error);
            compressImageFallback(file).then(resolve).catch(reject);
          }
        };

        worker.onerror = (err) => {
          worker.terminate();
          console.error('Worker error:', err);
          compressImageFallback(file).then(resolve).catch(reject);
        };

        worker.postMessage({ file, maxDimension: 1536, quality: 0.85 });
      } catch (e) {
        console.error('Failed to create worker:', e);
        compressImageFallback(file).then(resolve).catch(reject);
      }
    });
  };

  const processFile = async (file: File) => {
    if (!file.type.startsWith('image/')) {
      onError('Vui lòng chọn tệp hình ảnh hợp lệ (JPG, PNG, WebP).');
      return;
    }

    if (file.size === 0) {
      onError('File ảnh rỗng hoặc bị lỗi.');
      return;
    }

    setIsProcessing(true);
    try {
      // Use the worker-based compression
      const { base64, preview, mimeType } = await compressImageWithWorker(file);
      onImageSelected({
        file,
        previewUrl: preview,
        base64,
        mimeType
      });
    } catch (error: any) {
      console.error("Error processing image", error);
      onError(error.message || "Có lỗi khi xử lý hình ảnh. Vui lòng thử ảnh khác.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handlePasteClick = async (e: React.MouseEvent) => {
    e.stopPropagation(); // Stop bubbling to parent which triggers file input
    if (disabled || isProcessing) return;

    try {
      // Check if the Clipboard API is supported
      if (!navigator.clipboard || !navigator.clipboard.read) {
        onError("Trình duyệt của bạn không hỗ trợ nút dán này (yêu cầu HTTPS hoặc localhost). Hãy thử dùng phím tắt Ctrl+V.");
        return;
      }

      const clipboardItems = await navigator.clipboard.read();
      let found = false;

      for (const item of clipboardItems) {
        // Prioritize finding an image type
        const imageType = item.types.find(type => type.startsWith('image/'));
        if (imageType) {
          const blob = await item.getType(imageType);
          const file = new File([blob], "pasted_image", { type: imageType });
          processFile(file);
          found = true;
          break;
        }
      }

      if (!found) {
        onError("Không tìm thấy hình ảnh nào trong bộ nhớ tạm (Clipboard). Hãy copy ảnh trước.");
      }
    } catch (error) {
      console.error("Paste error:", error);
      onError("Không thể dán ảnh. Vui lòng cấp quyền truy cập bộ nhớ tạm hoặc sử dụng phím tắt Ctrl+V.");
    }
  };

  // Handle global paste event
  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      if (disabled || isProcessing) return;

      const items = e.clipboardData?.items;
      if (!items) return;

      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const file = items[i].getAsFile();
          if (file) {
            e.preventDefault();
            processFile(file);
            return;
          }
        }
      }
    };

    document.addEventListener('paste', handlePaste);
    return () => {
      document.removeEventListener('paste', handlePaste);
    };
  });

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (disabled || isProcessing) return;

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      processFile(e.target.files[0]);
    }
    // Reset input value to allow selecting the same file again if needed
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (disabled || isProcessing) return;
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      fileInputRef.current?.click();
    }
  };

  return (
    <div
      role="button"
      tabIndex={disabled ? -1 : 0}
      aria-label="Tải ảnh lên"
      onKeyDown={handleKeyDown}
      className={`relative group cursor-pointer transition-all duration-300 ease-out border-3 border-dashed rounded-[2rem] p-10 flex flex-col items-center justify-center text-center bg-white shadow-sm hover:shadow-xl focus:outline-none focus:ring-4 focus:ring-purple-200
        ${isDragging ? 'border-purple-500 bg-purple-50 scale-[1.01] shadow-xl' : 'border-gray-300 hover:border-purple-400'}
        ${disabled || isProcessing ? 'opacity-70 cursor-not-allowed pointer-events-none' : ''}
      `}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      onClick={() => fileInputRef.current?.click()}
    >
      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileChange}
        accept="image/*"
        className="hidden"
        disabled={disabled || isProcessing}
      />

      {isProcessing ? (
        <div className="flex flex-col items-center animate-fade-in">
           <div className="w-12 h-12 border-4 border-purple-200 border-t-purple-600 rounded-full animate-spin mb-4"></div>
           <p className="text-purple-600 font-bold text-lg">Đang tối ưu hóa ảnh...</p>
           <p className="text-sm text-gray-400 mt-2 max-w-xs">Hệ thống đang nén và chuẩn bị ảnh để gửi cho Gemini Vision</p>
        </div>
      ) : (
        <>
          <div className="w-24 h-24 mb-6 bg-purple-50 text-purple-600 rounded-full flex items-center justify-center transition-transform duration-300 group-hover:scale-110 group-hover:bg-purple-100 shadow-inner">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
            </svg>
          </div>

          <h3 className="text-2xl font-bold text-gray-800 mb-3">Tải ảnh lên</h3>
          <p className="text-gray-500 text-base max-w-sm mx-auto leading-relaxed mb-6">
            Kéo thả hoặc nhấp để chọn ảnh <br/>
            <span className="text-xs opacity-75">(Hỗ trợ JPG, PNG, WebP)</span>
          </p>

          <button
            type="button"
            onClick={handlePasteClick}
            className="relative z-10 mb-8 flex items-center gap-2 px-5 py-2.5 bg-white text-gray-700 font-semibold rounded-xl border border-gray-200 shadow-sm hover:bg-purple-50 hover:text-purple-700 hover:border-purple-200 hover:shadow-md transition-all duration-200 group/btn active:scale-95"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-gray-400 group-hover/btn:text-purple-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
            </svg>
            <span>Dán ảnh từ Clipboard</span>
          </button>
        </>
      )}
    </div>
  );
};

