                    <div className="flex flex-col">
                        <div className="flex items-center gap-2">
                            <span className={`font-bold text-sm ${isMain ? 'text-purple-900' : 'text-gray-700'}`}>
                                {isMain ? "Bản Sao Hoàn Hảo" : `Biến Thể ${index}`}
                            </span>
                            {/* Score Badge */}
                            {promptItem.score && (
                                <span className={`px-2 py-0.5 rounded-md text-[10px] font-bold shadow-sm ${getScoreColor(promptItem.score)}`}>
                                    {promptItem.score}/10
                                </span>
                            )}
                        </div>
                        {isMain && (
                             <span className="text-[10px] font-semibold text-purple-600 uppercase tracking-wider">
                                 High Fidelity Replication
                             </span>
                        )}
                    </div>
                 </div>

                 <div className="flex items-center gap-2">
                     {/* Optimize Button */}
                     <button
                        onClick={() => handleOptimizeClick(index)}
                        disabled={optimizingIndex === index || promptItem.score >= 10}
                        className={`p-2 rounded-xl transition-all duration-200 border flex items-center gap-2
                            ${optimizingIndex === index 
                                ? 'bg-purple-50 text-purple-400 border-purple-100 cursor-wait'
                                : promptItem.score >= 10 
                                  ? 'bg-gray-50 text-gray-300 border-gray-100 cursor-default'
                                  : 'bg-white text-purple-600 border-purple-100 hover:bg-purple-600 hover:text-white shadow-sm hover:shadow-purple-200'
                            }`}
                        title={promptItem.score >= 10 ? "Đã đạt điểm tối đa" : "Tối ưu hóa bằng AI"}
                     >
                        {optimizingIndex === index ? (
                             <svg className="animate-spin h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                               <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                               <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                             </svg>
                        ) : (
                             <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                               <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.384-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" />
                             </svg>
                        )}
                        <span className="hidden sm:inline text-xs font-bold">Tối ưu</span>
                     </button>

                     <button
                        onClick={() => handleCopy(promptItem.text, index)}
                        className={`p-2.5 rounded-xl transition-all duration-200 border
                            ${copiedIndex === index 
                                ? 'bg-green-100 text-green-700 border-green-200 shadow-inner' 
                                : 'bg-white text-gray-400 border-gray-100 hover:text-purple-600 hover:border-purple-200 hover:shadow-md'
                            }`}
                        title="Sao chép"
                     >
                        {copiedIndex === index ? (
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                                <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                            </svg>
                        ) : (
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3" />
                            </svg>
                        )}
                     </button>
                 </div>
              </div>

              {/* Card Body */}
              <div className="flex-grow p-6 bg-white cursor-text" onClick={() => {
                   // Optional: Click card body to copy? Maybe better not to interfere with selection.
              }}>
                <p className={`${selectedFont} text-sm leading-7 text-gray-700 whitespace-pre-wrap selection:bg-purple-100 selection:text-purple-900`}>
                    {promptItem.text}
                </p>
              </div>

              {/* Card Footer */}
              <div className="px-6 py-3 bg-gray-50/80 border-t border-gray-100 flex flex-wrap items-center justify-between gap-3">
                 <div className="flex items-center gap-2">
                    <span className="text-[10px] font-bold text-gray-400 uppercase tracking-wider bg-gray-100 px-2 py-1 rounded-md">
                        {promptItem.text.split(/\s+/).length} words
                    </span>
                 </div>

                 <button
                    onClick={() => handleUsePrompt(promptItem.text, index)}
                    className="group/btn flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-white border border-gray-200 text-xs font-bold text-gray-600 hover:text-indigo-600 hover:border-indigo-200 hover:shadow-sm transition-all"
                 >
                    <span>Dùng trên Whisk</span>
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 group-hover/btn:translate-x-0.5 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                    </svg>
                 </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { HistoryItem } from '../types';

interface HistoryListProps {
  history: HistoryItem[];
  onSelect: (item: HistoryItem) => void;
  onClear: () => void;
}

const ITEMS_PER_PAGE = 6;

export const HistoryList: React.FC<HistoryListProps> = ({ history, onSelect, onClear }) => {
  const [visibleCount, setVisibleCount] = useState(ITEMS_PER_PAGE);
  const observerTarget = useRef<HTMLDivElement>(null);

  // Reset visible count when history is cleared or dramatically changes
  useEffect(() => {
    if (history.length <= ITEMS_PER_PAGE) {
      setVisibleCount(ITEMS_PER_PAGE);
    }
  }, [history.length]);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
          setVisibleCount((prev) => Math.min(prev + ITEMS_PER_PAGE, history.length));
        }
      },
      { threshold: 0.1, rootMargin: '100px' }
    );

    const target = observerTarget.current;
    if (target) {
      observer.observe(target);
    }

    return () => {
      if (target) observer.unobserve(target);
      observer.disconnect();
    };
  }, [visibleCount, history.length]);

  if (history.length === 0) return null;

  const visibleHistory = history.slice(0, visibleCount);

  // Helper to safely get the first prompt text regardless of data version
  const getPreviewText = (result: any) => {
    if (!result || !result.prompts || result.prompts.length === 0) return "Không có nội dung";
    const firstPrompt = result.prompts[0];
    if (typeof firstPrompt === 'string') return firstPrompt;
    return firstPrompt.text || "Lỗi định dạng";
  };

  return (
    <div className="w-full mt-12 animate-fade-in">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-purple-100 rounded-lg text-purple-600">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
          </div>
          <h3 className="font-bold text-gray-800 text-xl">Lịch sử ({history.length})</h3>
        </div>
        <button
          onClick={onClear}
          className="text-sm text-red-500 hover:text-red-700 font-medium px-3 py-1.5 rounded-lg hover:bg-red-50 transition-colors"
        >
          Xóa tất cả
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
        {visibleHistory.map((item) => (
          <div
            key={item.id}
            onClick={() => onSelect(item)}
            className="group relative bg-white rounded-2xl p-3 border border-gray-100 shadow-sm hover:shadow-xl hover:-translate-y-1 hover:border-purple-200 transition-all duration-300 cursor-pointer overflow-hidden animate-fade-in-up"
          >
            <div className="flex gap-4">
              {/* Thumbnail */}
              <div className="w-20 h-20 shrink-0 rounded-xl overflow-hidden bg-gray-100 relative">
                <img
                  src={item.image.previewUrl}
                  alt="History thumbnail"
                  loading="lazy"
                  className="w-full h-full object-cover transform group-hover:scale-110 transition-transform duration-500 ease-out"
                />
              </div>

              {/* Info */}
              <div className="flex flex-col justify-center overflow-hidden">
                <p className="text-xs text-gray-400 font-medium mb-1">
                  {new Date(item.timestamp).toLocaleString('vi-VN')}
                </p>
                <p className="text-sm font-semibold text-gray-800 line-clamp-2 leading-snug group-hover:text-purple-700 transition-colors duration-300">
                  {getPreviewText(item.result)}
                </p>
              </div>
            </div>

            {/* Hover overlay */}
            <div className="absolute inset-0 bg-purple-600/5 opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none rounded-2xl" />
          </div>
        ))}
      </div>

      {/* Loading Sentinel */}
      {visibleCount < history.length && (
        <div ref={observerTarget} className="w-full py-6 flex justify-center items-center">
            <div className="w-6 h-6 border-2 border-purple-200 border-t-purple-600 rounded-full animate-spin"></div>
        </div>
      )}
    </div>
  );
};

