                            <li>Nếu ảnh quá mờ hoặc quá tối, hãy thử ảnh chất lượng tốt hơn.</li>
                            <li>Thử tải lại trang và thực hiện lại.</li>
                          </ul>
                        </div>

                        <button 
                          onClick={handleRetry} 
                          className="w-full py-3 bg-red-600 hover:bg-red-700 text-white font-bold rounded-xl shadow-lg shadow-red-200 transition-all active:scale-95 flex justify-center items-center gap-2"
                        >
                           <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                             <path fillRule="evenodd" d="M4 2a1 1 0 011 1v2.101a7.002 7.002 0 0111.601 2.566 1 1 0 11-1.885.666A5.002 5.002 0 005.999 7H9a1 1 0 010 2H4a1 1 0 01-1-1V3a1 1 0 011-1zm.008 9.057a1 1 0 011.276.61A5.002 5.002 0 0014.001 13H11a1 1 0 110-2h5a1 1 0 011 1v3.279a1 1 0 11-2 0V12.9a7.002 7.002 0 01-11.601-2.566 1 1 0 01.61-1.276z" clipRule="evenodd" />
                           </svg>
                           Thử lại ngay
                        </button>
                      </motion.div>
                   )}
                </div>

                {/* Bottom: Results or Loading */}
                <div className="w-full" ref={resultsRef}>
                   {/* IDLE state placeholder removed as we usually jump to analyzing immediately */}

                   {appState === AppState.ANALYZING && <SkeletonLoader />}

                   {appState === AppState.SUCCESS && analysisResult && (
                     <div className="flex flex-col gap-6">
                       <PromptDisplay 
                          prompts={analysisResult.prompts} 
                          suggestions={analysisResult.suggestions}
                          onOptimize={handleOptimize}
                       />
                       <SuggestionsDisplay suggestions={analysisResult.suggestions} />
                       <WhiskGuide />
                       <button 
                          onClick={handleReset} 
                          className="md:hidden w-full py-3 bg-white border border-gray-200 text-gray-600 rounded-xl font-medium shadow-sm active:bg-gray-50"
                        >
                          Giải mã ảnh khác
                        </button>
                     </div>
                   )}
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>

      {/* Enhanced Footer */}
      <footer className="py-8 border-t border-gray-100 bg-white/60 backdrop-blur-sm mt-auto">
        <div className="max-w-5xl mx-auto px-4 text-center">
          <p className="text-gray-400 text-xs">@2025 Trợ Lý Bé Điệu</p>
        </div>
      </footer>

      {/* Scroll to Top Button */}
      {showScrollTop && (
        <button
          onClick={scrollToTop}
          className="fixed bottom-8 right-8 z-50 p-3 bg-white/80 backdrop-blur-md border border-purple-100 text-purple-600 rounded-full shadow-lg hover:bg-purple-600 hover:text-white hover:shadow-purple-200 transition-all duration-300 transform hover:scale-110 active:scale-95 animate-fade-in"
          aria-label="Cuộn lên đầu trang"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 10l7-7m0 0l7 7m-7-7v18" />
          </svg>
        </button>
      )}
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, PromptItem } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key chưa được cấu hình trong hệ thống. Vui lòng kiểm tra biến môi trường.");
  }
  return new GoogleGenAI({ apiKey });
};

export const decodeImagePrompt = async (base64Data: string, mimeType: string, count: number = 1): Promise<AnalysisResult> => {
  try {
    const ai = getClient();

    const imagePart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Data
      }
    };

    const promptText = `
      Đóng vai một **Giám đốc Sáng tạo (Creative Director)** và **Nhiếp ảnh gia Thời trang Cao cấp**. Nhiệm vụ của bạn là giải mã hình ảnh để viết prompt tái tạo với độ chính xác tuyệt đối.

      Thực hiện phân tích "Layered Visual Surgery" (Thông số kỹ thuật, Chất liệu/Fashion, Chủ thể/Vibe).

      **YÊU CẦU OUTPUT JSON:**

      - "prompts": Mảng chứa ${count} đối tượng. Mỗi đối tượng gồm:
        *   "text": Chuỗi văn bản prompt Tiếng Anh.
            - **Index 0 (The Replica):** Tái tạo chính xác 100% ảnh gốc.
            - **Index 1+ (The Lookbook):** Các biến thể sáng tạo (Texture Focus, Dramatic Lighting, Dynamic Motion, Environmental Story, Creative Perspective/Angles).
        *   "score": Số nguyên từ 1 đến 10. Đánh giá chất lượng của prompt này dựa trên độ chi tiết, tính nghệ thuật và khả năng tạo ảnh đẹp (Midjourney/Flux standard).

      - "suggestions": 3-5 gợi ý ngắn gọn (Tiếng Việt) để cải thiện ảnh.

      Đảm bảo JSON hợp lệ. Không markdown.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [imagePart, { text: promptText }]
      },
      config: {
        temperature: 0.75,
        topK: 40,
        topP: 0.95,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prompts: {
              type: Type.ARRAY,
              items: { 
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING },
                  score: { type: Type.NUMBER, description: "Rating 1-10" }
                },
                required: ["text", "score"]
              }
            },
            suggestions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["prompts", "suggestions"]
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("AI không trả về nội dung nào.");
    }

    try {
      return JSON.parse(text) as AnalysisResult;
    } catch (e) {
      throw new Error("Lỗi định dạng dữ liệu từ AI.");
    }

  } catch (error: any) {
    console.error("Lỗi khi gọi Gemini API:", error);
    throw new Error(error.message || "Đã xảy ra lỗi không xác định khi phân tích hình ảnh.");
  }
};

export const optimizePrompt = async (originalPrompt: string): Promise<PromptItem> => {
  try {
    const ai = getClient();
    const promptText = `
      Bạn là một chuyên gia Prompt Engineering hàng đầu thế giới (Midjourney v6 & Flux expert).
      Nhiệm vụ: Nâng cấp prompt dưới đây lên mức điểm 10/10.

      Prompt gốc: "${originalPrompt}"

      Yêu cầu tối ưu hóa:
      1. Thêm các từ khóa nghệ thuật (artistic keywords).
      2. Cụ thể hóa ánh sáng (Cinematic lighting, Volumetric, v.v.).
      3. Chi tiết hóa chất liệu (hyper-detailed textures).
      4. Bổ sung thông số camera (nếu thiếu).
      5. Giữ nguyên ý tưởng cốt lõi, chỉ làm cho nó đẹp hơn và chuyên nghiệp hơn.

      Output JSON format:
      {
        "text": "Prompt đã tối ưu (Tiếng Anh)",
        "score": 10
      }
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
         parts: [{ text: promptText }]
      },
      config: {
        temperature: 0.8,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            text: { type: Type.STRING },
            score: { type: Type.NUMBER }
          },
          required: ["text", "score"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response");
    return JSON.parse(text) as PromptItem;

  } catch (error: any) {
     console.error("Optimize error:", error);
     throw new Error("Không thể tối ưu hóa prompt lúc này.");
  }
};

