// Inline Skeleton Component for smoother state transitions
const SkeletonLoader = () => {
  const [loadingText, setLoadingText] = useState('Đang khởi tạo kết nối...');
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const steps = [
      'Đang khởi tạo kết nối với Gemini Vision...',
      'Đang quét chi tiết khuôn mặt và thần thái...',
      'Đang phân tích chất liệu trang phục và phụ kiện...',
      'Đang giải mã setup ánh sáng và bố cục...',
      'Đang xác định thông số máy ảnh và ống kính...',
      'Đang tổng hợp dữ liệu để viết prompt...',
      'Đang tạo các biến thể góc chụp sáng tạo...',
    ];

    let stepIndex = 0;

    // Rotate text messages every 2.5 seconds
    const textInterval = setInterval(() => {
      stepIndex = (stepIndex + 1) % steps.length;
      setLoadingText(steps[stepIndex]);
    }, 2500);

    // Simulate progress bar (asymptotic to 95%)
    const progressInterval = setInterval(() => {
      setProgress(prev => {
        // Slow down as it reaches higher percentages
        const increment = prev < 30 ? 2 : prev < 60 ? 1 : prev < 85 ? 0.5 : 0.1;
        const next = prev + increment;
        return next > 95 ? 95 : next;
      });
    }, 100);

    return () => {
      clearInterval(textInterval);
      clearInterval(progressInterval);
    };
  }, []);

  return (
    <div className="w-full bg-white rounded-3xl shadow-xl overflow-hidden border border-gray-100 flex flex-col min-h-[400px]">
      {/* Header Skeleton */}
      <div className="bg-gray-50/50 px-6 py-5 border-b border-gray-100 flex items-center justify-between">
        <div className="h-6 bg-gray-200 rounded-lg w-32 animate-pulse"></div>
        <div className="h-9 bg-gray-200 rounded-xl w-24 animate-pulse"></div>
      </div>

      <div className="p-8 flex-grow flex flex-col justify-center items-center relative">
        {/* Background content skeletons (faded) */}
        <div className="w-full space-y-4 mb-12 opacity-30 blur-[1px]">
           <div className="h-4 bg-gray-200 rounded w-full"></div>
           <div className="h-4 bg-gray-200 rounded w-11/12"></div>
           <div className="h-4 bg-gray-200 rounded w-full"></div>
           <div className="h-4 bg-gray-200 rounded w-3/4"></div>
           <div className="h-4 bg-gray-200 rounded w-5/6"></div>
           <div className="h-4 bg-gray-200 rounded w-full"></div>
        </div>

        {/* Central Loading Indicator */}
        <div className="absolute inset-0 flex flex-col items-center justify-center z-10 bg-white/50 backdrop-blur-sm">
          <div className="relative w-20 h-20 mb-6">
             {/* Outer spinning ring */}
             <div className="absolute inset-0 border-4 border-purple-100 rounded-full"></div>
             <div className="absolute inset-0 border-4 border-purple-600 rounded-full border-t-transparent animate-spin"></div>

             {/* Inner pulsing icon */}
             <div className="absolute inset-0 flex items-center justify-center">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-purple-600 animate-pulse" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.384-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" />
                </svg>
             </div>
          </div>

          <div className="text-center space-y-3 max-w-sm px-4">
             <p className="text-gray-800 font-bold text-lg min-h-[28px] transition-all duration-300">
               {loadingText}
             </p>

             {/* Progress Bar */}
             <div className="w-64 h-2 bg-gray-100 rounded-full overflow-hidden mx-auto shadow-inner">
               <div 
                 className="h-full bg-gradient-to-r from-purple-500 via-indigo-500 to-blue-500 transition-all duration-300 ease-out"
                 style={{ width: `${progress}%` }}
               />
             </div>

             <p className="text-xs text-gray-400 font-mono pt-1">
               AI Processing: {Math.floor(progress)}%
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

interface ErrorDetails {
  title: string;
  message: string;
  suggestions: string[];
  type: 'safety' | 'network' | 'quota' | 'generic';
}

const App: React.FC = () => {
  const [image, setImage] = useState<ImageFile | null>(null);
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(null);
  const [errorDetails, setErrorDetails] = useState<ErrorDetails | null>(null);
  const [promptCount, setPromptCount] = useState<number>(10);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [showScrollTop, setShowScrollTop] = useState(false);

  const resultsRef = useRef<HTMLDivElement>(null);

  // Helper to normalize prompt data (string -> object migration)
  const normalizePrompts = (prompts: any[]): PromptItem[] => {
    return prompts.map(p => {
      if (typeof p === 'string') {
        return { text: p, score: 0 };
      }
      return p;
    });
  };

  // Analyze raw error to provide better feedback
  const analyzeError = (error: any): ErrorDetails => {
    const msg = (error.message || JSON.stringify(error)).toLowerCase();

    // 1. Safety / Policy Violations
    if (msg.includes('safety') || msg.includes('blocked') || msg.includes('harmful') || msg.includes('sexually')) {
      return {
        title: "Nội dung bị từ chối",
        message: "AI phát hiện hình ảnh chứa nội dung nhạy cảm, bạo lực hoặc vi phạm chính sách an toàn của Google.",
        type: 'safety',
        suggestions: [
          "Thử một hình ảnh khác 'lành mạnh' hơn.",
          "Che bớt các vùng da thịt nhạy cảm hoặc yếu tố bạo lực (máu me, vũ khí).",
          "Đây là cơ chế an toàn tự động của AI, không phải lỗi hệ thống."
        ]
      };
    }

    // 2. Network / Connection
    if (msg.includes('fetch') || msg.includes('network') || msg.includes('connection') || msg.includes('offline')) {
      return {
        title: "Lỗi kết nối mạng",
        message: "Không thể kết nối đến máy chủ AI. Vui lòng kiểm tra đường truyền Internet của bạn.",
        type: 'network',
        suggestions: [
          "Kiểm tra kết nối Wifi hoặc 4G/5G.",
          "Tắt VPN hoặc Adblock nếu đang bật.",
          "Thử tải lại trang (F5) và thực hiện lại."
        ]
      };
    }

    // 3. Quota / Rate Limit
    if (msg.includes('429') || msg.includes('quota') || msg.includes('resource exhausted')) {
      return {
        title: "Hệ thống quá tải (Rate Limit)",
        message: "API Key đang bị giới hạn số lượng yêu cầu trong thời gian ngắn.",
        type: 'quota',
        suggestions: [
          "Vui lòng chờ khoảng 1-2 phút rồi thử lại.",
          "Hệ thống đang sử dụng gói miễn phí nên có giới hạn tần suất gọi.",
        ]
      };
    }

    // 4. Image Data Issues
    if (msg.includes('image') || msg.includes('format') || msg.includes('base64')) {
        return {
            title: "Lỗi dữ liệu hình ảnh",
            message: "Không thể đọc hoặc xử lý file ảnh này.",
            type: 'generic',
            suggestions: [
              "Đảm bảo ảnh là định dạng JPG, PNG hoặc WebP.",
              "Thử nén ảnh hoặc dùng ảnh có dung lượng nhỏ hơn (dưới 10MB).",
              "Chọn một ảnh khác để kiểm tra."
            ]
        };
    }

    // 5. Default Generic Error
    return {
      title: "Đã xảy ra lỗi không mong muốn",
      message: error.message || "Hệ thống gặp sự cố khi xử lý yêu cầu này.",
      type: 'generic',
      suggestions: [
        "Thử tải lại trang.",
        "Thử lại sau vài phút.",
        "Nếu lỗi vẫn tiếp diễn, có thể server đang bảo trì."
      ]
    };
  };

  // Load share URL param on mount
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const shareData = params.get('share');
    if (shareData) {
      try {
        const json = JSON.parse(decodeURIComponent(escape(atob(shareData))));
        if (json.p && Array.isArray(json.p)) {
          setAnalysisResult({
            prompts: normalizePrompts(json.p),
            suggestions: json.s || []
          });
          setAppState(AppState.SUCCESS);
        }
      } catch (e) {
        console.error("Invalid share data", e);
        handleError(new Error("Liên kết chia sẻ không hợp lệ hoặc đã bị lỗi."));
      }
    }
  }, []);

  // Load history from localStorage on mount
  useEffect(() => {
    try {
      const savedHistory = localStorage.getItem('promptDecoderHistory');
      if (savedHistory) {
        const parsed = JSON.parse(savedHistory);
        const normalized = parsed.map((item: any) => ({
           ...item,
           result: {
             ...item.result,
             prompts: normalizePrompts(item.result.prompts)
           }
        }));
        setHistory(normalized);
      }
    } catch (error) {
      console.error("Failed to load history", error);
    }
  }, []);

  // Save history to localStorage whenever it changes
  useEffect(() => {
    try {
      localStorage.setItem('promptDecoderHistory', JSON.stringify(history));
    } catch (error) {
      console.error("Failed to save history", error);
    }
  }, [history]);

  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 400) {
        setShowScrollTop(true);
      } else {
        setShowScrollTop(false);
      }
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth',
    });
  };

  const addToHistory = (img: ImageFile, result: AnalysisResult) => {
    const newItem: HistoryItem = {
      id: Date.now().toString(),
      timestamp: Date.now(),
      image: img,
      result: result
    };
    setHistory(prev => [newItem, ...prev].slice(0, 24));
  };

  const handleError = (error: any) => {
    const details = analyzeError(error);
    setErrorDetails(details);
    setAppState(AppState.ERROR);
  };

  const performAnalysis = async (img: ImageFile) => {
    setAppState(AppState.ANALYZING);
    setErrorDetails(null);

    try {
      const result = await decodeImagePrompt(img.base64, img.mimeType, promptCount);
      setAnalysisResult(result);
      setAppState(AppState.SUCCESS);
      addToHistory(img, result);

      if (window.location.search.includes('share=')) {
        window.history.pushState({}, '', window.location.pathname);
      }
    } catch (error: any) {
      console.error("Analysis failed", error);
      handleError(error);
    }
  };

  const handleOptimize = async (index: number) => {
    if (!analysisResult) return;

    const originalItem = analysisResult.prompts[index];
    try {
        const optimizedItem = await optimizePrompt(originalItem.text);

        const newPrompts = [...analysisResult.prompts];
        newPrompts[index] = optimizedItem;

        const newResult = {
            ...analysisResult,
            prompts: newPrompts
        };

        setAnalysisResult(newResult);

        // Update History to save the optimization
        setHistory(prev => {
            if (prev.length === 0) return prev;
            // Update the most recent item (or matching by content logic if we had IDs)
            // Here we assume the user is optimizing the currently viewed prompt which is often the first in history or selected
            // Since we don't track "selectedHistoryId", we update the item that matches the image preview or timestamp
            const updated = [...prev];
            // Simple heuristic: Update the first item if we just generated it
            // Or if we are in view mode, we might need to know WHICH history item is active.
            // For simplicity in this scope: We update the history item at index 0 if it matches the current prompts count, 
            // otherwise we just leave history as is (only updating view).

            // To be more robust, we could track currentHistoryId.
            // But for this request, let's just update if it's the latest one.
            if (updated[0] && updated[0].result.prompts.length === newPrompts.length) { 
                 updated[0] = { ...updated[0], result: newResult };
            }
            return updated;
        });

    } catch (e: any) {
        alert(e.message || "Tối ưu hóa thất bại");
    }
  };

  const handleImageSelected = (selectedImage: ImageFile) => {
    setImage(selectedImage);
    setAnalysisResult(null);
    setErrorDetails(null);
    performAnalysis(selectedImage);
  };

  const handleReset = () => {
    setImage(null);
    setAppState(AppState.IDLE);
    setAnalysisResult(null);
    setErrorDetails(null);
    if (window.location.search.includes('share=')) {
      window.history.pushState({}, '', window.location.pathname);
    }
  };

  const handleRetry = () => {
    if (!image) return;
    performAnalysis(image);
  };

  const handleSelectHistory = (item: HistoryItem) => {
    setImage(item.image);
    setAnalysisResult({
        ...item.result,
        prompts: normalizePrompts(item.result.prompts)
    });
    setAppState(AppState.SUCCESS);
    setErrorDetails(null);
    if (window.location.search.includes('share=')) {
        window.history.pushState({}, '', window.location.pathname);
    }
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleClearHistory = () => {
    if (window.confirm("Bạn có chắc chắn muốn xóa toàn bộ lịch sử không?")) {
      setHistory([]);
    }
  };

  // Logic to determine view state
  const isSharedMode = !image && analysisResult !== null;
  const showResultsView = !!(image || isSharedMode);
  const showHomeView = !showResultsView;

  // Render Error Box Component
  const ErrorDisplay = ({ details }: { details: ErrorDetails }) => {
     const isSafety = details.type === 'safety';
     const isNetwork = details.type === 'network';
     const isQuota = details.type === 'quota';

     let icon = (
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
        </svg>
     );

     if (isSafety) {
         icon = (
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
            </svg>
         );
     } else if (isNetwork) {
         icon = (
             <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M18.364 5.636a9 9 0 010 12.728m0 0l-2.829-2.829m2.829 2.829L21 21M15.536 8.464a5 5 0 010 7.072m0 0l-2.829-2.829m-4.243 2.829a4.978 4.978 0 01-1.414-2.83m-1.414 5.658a9 9 0 01-2.167-9.238m7.824 2.167a1 1 0 111.414 1.414m-1.414-1.414L3 3m8.293 8.293l1.414 1.414" />
             </svg>
         );
     } else if (isQuota) {
         icon = (
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
         );
     }

     return (
        <motion.div 
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className={`w-full bg-white rounded-3xl p-6 shadow-xl border flex flex-col gap-4 ring-1
                ${isSafety ? 'border-amber-100 ring-amber-50' : 'border-red-100 ring-red-50'}
            `}
        >
            <div className="flex items-start gap-4">
                <div className={`p-3 rounded-xl shrink-0 ${isSafety ? 'bg-amber-100 text-amber-600' : 'bg-red-100 text-red-600'}`}>
                    {icon}
                </div>
                <div className="flex-grow">
                    <h3 className="text-lg font-bold text-gray-900">{details.title}</h3>
                    <p className={`${isSafety ? 'text-amber-800' : 'text-red-700'} font-medium mt-1 leading-relaxed`}>
                        {details.message}
                    </p>
                </div>
            </div>

            <div className={`rounded-xl p-5 text-sm ${isSafety ? 'bg-amber-50 text-amber-900' : 'bg-red-50 text-gray-700'}`}>
                <p className="font-bold mb-3 uppercase text-xs tracking-wider opacity-70">Gợi ý khắc phục:</p>
                <ul className="space-y-2">
                    {details.suggestions.map((suggestion, idx) => (
                        <li key={idx} className="flex items-start gap-2">
                            <span className="mt-1.5 w-1.5 h-1.5 rounded-full bg-current opacity-60 flex-shrink-0"></span>
                            <span>{suggestion}</span>
                        </li>
                    ))}
                </ul>
            </div>

            <div className="flex flex-col sm:flex-row gap-3 pt-2">
                <button 
                    onClick={handleRetry} 
                    className="flex-1 py-3 bg-red-600 hover:bg-red-700 text-white font-bold rounded-xl shadow-lg shadow-red-200 transition-all active:scale-95 flex justify-center items-center gap-2"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M4 2a1 1 0 011 1v2.101a7.002 7.002 0 0111.601 2.566 1 1 0 11-1.885.666A5.002 5.002 0 005.999 7H9a1 1 0 010 2H4a1 1 0 01-1-1V3a1 1 0 011-1zm.008 9.057a1 1 0 011.276.61A5.002 5.002 0 0014.001 13H11a1 1 0 110-2h5a1 1 0 011 1v3.279a1 1 0 11-2 0V12.9a7.002 7.002 0 01-11.601-2.566 1 1 0 01.61-1.276z" clipRule="evenodd" />
                    </svg>
                    Thử lại
                </button>
                <button 
                    onClick={handleReset} 
                    className="flex-1 py-3 bg-white border border-gray-200 hover:bg-gray-50 text-gray-700 font-bold rounded-xl transition-all active:scale-95 flex justify-center items-center gap-2"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                    </svg>
                    Chọn ảnh khác
                </button>
            </div>
        </motion.div>
     );
  };

  return (
    <div className="min-h-screen flex flex-col font-sans selection:bg-purple-200 selection:text-purple-900 relative">
      <div className="flex-grow w-full max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        <Header />

        <div className="mt-8 mb-12 relative min-h-[400px]">
          <AnimatePresence mode="wait" initial={false}>
            {showHomeView ? (
              <motion.div
                key="home"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                transition={{ duration: 0.3, ease: "easeOut" }}
                className="max-w-3xl mx-auto flex flex-col gap-6"
              >
                {/* Configuration Panel */}
                <div className="bg-white rounded-2xl p-4 shadow-sm border border-gray-100 flex flex-col sm:flex-row items-center justify-between gap-4">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-blue-50 text-blue-600 rounded-lg">
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4" />
                      </svg>
                    </div>
                    <div>
                      <h3 className="font-semibold text-gray-800">Số lượng Prompt</h3>
                      <p className="text-xs text-gray-500">Tạo nhiều biến thể dựa trên phong cách gốc</p>
                    </div>
                  </div>

                  <div className="flex items-center gap-2 bg-gray-50 p-1.5 rounded-xl border border-gray-200">
                    <button 
                      onClick={() => setPromptCount(Math.max(1, promptCount - 1))}
                      className="w-8 h-8 flex items-center justify-center rounded-lg bg-white text-gray-600 shadow-sm hover:bg-gray-100 disabled:opacity-50 transition-colors"
                      disabled={promptCount <= 1}
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 12H4" />
                      </svg>
                    </button>
                    <input
                      type="number"
                      min="1"
                      value={promptCount}
                      onChange={(e) => {
                        const val = parseInt(e.target.value);
                        if (!isNaN(val) && val > 0) {
                          setPromptCount(val);
                        }
                      }}
                      className="w-12 text-center font-bold text-gray-800 bg-transparent outline-none appearance-none focus:ring-2 focus:ring-purple-100 rounded-md py-0.5"
                      aria-label="Nhập số lượng prompt"
                    />
                    <button 
                      onClick={() => setPromptCount(promptCount + 1)}
                      className="w-8 h-8 flex items-center justify-center rounded-lg bg-white text-gray-600 shadow-sm hover:bg-gray-100 transition-colors"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                      </svg>
                    </button>
                  </div>
                </div>

                <div className="transform transition-all duration-500 hover:-translate-y-1">
                  <ImageUploader onImageSelected={handleImageSelected} onError={handleError} />
                </div>

                {/* Home View Error Display (e.g. upload failed) */}
                {appState === AppState.ERROR && errorDetails && !image && (
                   <motion.div 
                    initial={{ opacity: 0, height: 0 }}
                    animate={{ opacity: 1, height: 'auto' }}
                    className="bg-red-50 border border-red-100 rounded-2xl p-6 flex flex-col gap-3 shadow-sm"
                   >
                      <div className="flex items-start gap-3">
                        <div className="p-3 bg-red-100 rounded-xl text-red-600 shrink-0">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                            </svg>
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-gray-900">{errorDetails.title}</h3>
                            <p className="text-gray-600 mt-1">{errorDetails.message}</p>
                        </div>
                      </div>

                      {/* Suggestion list for home error */}
                      <div className="pl-14">
                        <ul className="list-disc pl-5 space-y-1 text-sm text-gray-500">
                             {errorDetails.suggestions.map((s, i) => <li key={i}>{s}</li>)}
                        </ul>
                      </div>
                   </motion.div>
                )}

                <HistoryList 
                  history={history} 
                  onSelect={handleSelectHistory} 
                  onClear={handleClearHistory} 
                />
              </motion.div>
            ) : (
              <motion.div
                key="results"
