        >
            <div className="flex items-start gap-4">
                <div className={`p-3 rounded-xl shrink-0 ${isSafety ? 'bg-amber-100 text-amber-600' : 'bg-red-100 text-red-600'}`}>
                    {icon}
                </div>
                <div className="flex-grow">
                    <h3 className="text-lg font-bold text-gray-900">{details.title}</h3>
                    <p className={`${isSafety ? 'text-amber-800' : 'text-red-700'} font-medium mt-1 leading-relaxed`}>
                        {details.message}
                    </p>
                </div>
            </div>

            <div className={`rounded-xl p-5 text-sm ${isSafety ? 'bg-amber-50 text-amber-900' : 'bg-red-50 text-gray-700'}`}>
                <p className="font-bold mb-3 uppercase text-xs tracking-wider opacity-70">Gợi ý khắc phục:</p>
                <ul className="space-y-2">
                    {details.suggestions.map((suggestion, idx) => (
                        <li key={idx} className="flex items-start gap-2">
                            <span className="mt-1.5 w-1.5 h-1.5 rounded-full bg-current opacity-60 flex-shrink-0"></span>
                            <span>{suggestion}</span>
