import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult, PromptItem } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key chưa được cấu hình trong hệ thống. Vui lòng kiểm tra biến môi trường.");
  }
  return new GoogleGenAI({ apiKey });
};

export const decodeImagePrompt = async (base64Data: string, mimeType: string, count: number = 1): Promise<AnalysisResult> => {
  try {
    const ai = getClient();

    const imagePart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Data
      }
    };

    const promptText = `
      Bạn là một **Chuyên gia Phân tích Hình ảnh Pháp y (Forensic Image Analyst)** và **Giám đốc Nghệ thuật AI (Midjourney/Flux Expert)**.

      **NHIỆM VỤ:** Giải mã hình ảnh đầu vào để tạo ra các prompt tái tạo cực kỳ chính xác.

      **QUY TẮC BẤT DI BẤT DỊCH (CONSTANTS - GIỮ NGUYÊN 100%):**
      1. **Bố cục & Ngữ cảnh:** Giữ nguyên background, setting, props, môi trường xung quanh.
      2. **Phong cách & Chất liệu:** Giữ nguyên style nghệ thuật (Realism, Anime, Oil Painting...), chất liệu trang phục (fabric, texture), trang sức (jewelry details), phụ kiện.
      3. **Ánh sáng & Màu sắc:** Giữ nguyên setup ánh sáng (Volumetric, Rembrant...), color grading, film stock (Kodak, Fujifilm...).
      4. **Văn bản (Text):** Nếu trong ảnh có chữ, phải trích xuất chính xác và đưa vào prompt trong dấu ngoặc kép.

      **BIẾN SỐ (VARIABLES - CHỈ THAY ĐỔI CÁC YẾU TỐ SAU CHO CÁC BIẾN THỂ):**
      - Góc chụp khuôn mặt (Face Angle: Profile, Frontal, 3/4 view...).
      - Dáng đứng/ngồi (Pose: Dynamic, Static, Candid...).
      - Khoảng cách camera với chủ thể (Shot size: Close-up, Medium shot, Cowboy shot...).
      *Lưu ý: Dù thay đổi pose, nhưng trang phục và background phải tuyệt đối đồng nhất với ảnh gốc.*

      **YÊU CẦU OUTPUT JSON:**

      - "prompts": Mảng chứa ${count} đối tượng.
        * "text": Prompt Tiếng Anh. 
           - Prompt #1: Tái tạo chính xác 100% ảnh gốc (The Replica).
           - Prompt #2+: Giữ nguyên mọi thứ (Môi trường, Đồ vật, Quần áo, Text), CHỈ thay đổi Pose/Angle/Distance của chủ thể.
        * "score": Đánh giá chất lượng (1-10).

      - "detectedTexts": Mảng chứa các chuỗi văn bản (text) tìm thấy trong ảnh. Nếu không có thì để mảng rỗng.

      - "suggestions": 3-5 gợi ý ngắn (Tiếng Việt) để cải thiện ảnh (ví dụ: đổi lens, thêm fill light).

      Không dùng markdown. Chỉ trả về JSON thuần.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [imagePart, { text: promptText }]
      },
      config: {
        temperature: 0.7, // Giảm temperature để tăng độ ổn định/nhất quán
        topK: 40,
        topP: 0.95,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prompts: {
              type: Type.ARRAY,
              items: { 
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING },
                  score: { type: Type.NUMBER, description: "Rating 1-10" }
                },
                required: ["text", "score"]
              }
            },
            detectedTexts: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "List of exact text strings visible in the image"
            },
            suggestions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["prompts", "suggestions"]
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("AI không trả về nội dung nào.");
    }

    try {
      return JSON.parse(text) as AnalysisResult;
    } catch (e) {
      throw new Error("Lỗi định dạng dữ liệu từ AI.");
    }

  } catch (error: any) {
    console.error("Lỗi khi gọi Gemini API:", error);
    throw new Error(error.message || "Đã xảy ra lỗi không xác định khi phân tích hình ảnh.");
  }
};

export const optimizePrompt = async (originalPrompt: string): Promise<PromptItem> => {
  try {
    const ai = getClient();
    const promptText = `
      Bạn là một chuyên gia Prompt Engineering (Midjourney v6/Flux).
      Nhiệm vụ: Nâng cấp prompt sau lên điểm 10/10 (Photorealistic/High Art).

      Prompt gốc: "${originalPrompt}"

      Yêu cầu:
      1. Giữ nguyên ý nghĩa, nội dung text (nếu có), màu sắc và bố cục gốc.
      2. Bổ sung từ khóa về chất lượng: "8k resolution, hyper-detailed, photorealistic, masterpiece, cinematic lighting, ray tracing".
      3. Làm rõ chất liệu (texture) và quang học (camera lens, depth of field).

      Output JSON: { "text": "...", "score": 10 }
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
         parts: [{ text: promptText }]
      },
      config: {
        temperature: 0.7,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            text: { type: Type.STRING },
            score: { type: Type.NUMBER }
          },
          required: ["text", "score"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response");
    return JSON.parse(text) as PromptItem;

  } catch (error: any) {
     console.error("Optimize error:", error);
     throw new Error("Không thể tối ưu hóa prompt lúc này.");
  }
};

import React, { useState, useEffect } from 'react';
import { PromptItem } from '../types';

interface PromptDisplayProps {
  prompts: PromptItem[];
  suggestions: string[];
  detectedTexts?: string[];
  onOptimize: (index: number) => Promise<void>;
  onOptimizeAll: () => Promise<void>;
}

type FontType = 'font-mono' | 'font-sans' | 'font-serif';

export const PromptDisplay: React.FC<PromptDisplayProps> = ({ prompts, suggestions, detectedTexts = [], onOptimize, onOptimizeAll }) => {
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);
  const [copiedAll, setCopiedAll] = useState(false);
  const [shared, setShared] = useState(false);
  const [selectedFont, setSelectedFont] = useState<FontType>('font-mono');
  const [optimizingIndex, setOptimizingIndex] = useState<number | null>(null);
  const [isOptimizingAll, setIsOptimizingAll] = useState(false);

  // State for text overrides
  const [textOverrides, setTextOverrides] = useState<Record<string, string>>({});

  // Initialize overrides when detectedTexts change
  useEffect(() => {
    const initialOverrides: Record<string, string> = {};
    detectedTexts.forEach(text => {
      initialOverrides[text] = text;
    });
    setTextOverrides(initialOverrides);
  }, [detectedTexts]);

  const handleTextOverrideChange = (original: string, newValue: string) => {
    setTextOverrides(prev => ({
      ...prev,
      [original]: newValue
    }));
  };

  // Helper function to apply text overrides to a prompt string
  const getDisplayPrompt = (originalPromptText: string): string => {
    let finalPrompt = originalPromptText;
    detectedTexts.forEach(original => {
      const replacement = textOverrides[original];
      if (replacement && replacement !== original) {
        // Replace all occurrences of the original text with the replacement
        // Using split/join or regex to replace global
        finalPrompt = finalPrompt.split(original).join(replacement);
      }
    });
    return finalPrompt;
  };

  const handleCopy = async (text: string, index: number) => {
    try {
      // Use the overridden text
      const textToCopy = getDisplayPrompt(text);
      await navigator.clipboard.writeText(textToCopy);
      setCopiedIndex(index);
      setTimeout(() => setCopiedIndex(null), 2000);
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  const handleCopyAll = async () => {
    try {
      const allText = prompts.map(p => getDisplayPrompt(p.text)).join('\n\n');
      await navigator.clipboard.writeText(allText);
      setCopiedAll(true);
      setTimeout(() => setCopiedAll(false), 2000);
    } catch (err) {
      console.error('Failed to copy all text: ', err);
    }
  };

  const handleShare = async () => {
    try {
      const shareData = {
        p: prompts,
        s: suggestions,
        t: detectedTexts // Share detected texts too potentially, though prompts have them embedded
      };
      const jsonString = JSON.stringify(shareData);
      const encoded = btoa(unescape(encodeURIComponent(jsonString)));
      const url = new URL(window.location.href);
      url.searchParams.set('share', encoded);
      const shareUrl = url.toString();
      await navigator.clipboard.writeText(shareUrl);
      window.history.pushState({}, '', shareUrl);
      setShared(true);
      setTimeout(() => setShared(false), 2000);
    } catch (err) {
      console.error('Failed to generate share link: ', err);
    }
  };

  const handleUsePrompt = (text: string, index: number) => {
      handleCopy(text, index);
      window.open('https://labs.google/fx/tools/whisk/project', '_blank');
  };

  const handleOptimizeClick = async (index: number) => {
    if (optimizingIndex !== null || isOptimizingAll) return;
    setOptimizingIndex(index);
    try {
      // NOTE: Optimization currently uses the original prompt text to send to AI.
      // If we want AI to optimize the *modified* text, we should pass the modified version.
      // However, optimizing the *structure* of the prompt is usually the goal.
      // Let's pass the prompt as displayed so the new text is included in optimization.

      /* 
       * Issue: The parent `onOptimize` likely updates the original prompts state. 
       * If we send the modified text, the AI returns a new prompt.
       * The detected text structure might be lost in the new prompt.
       * For simplicity in this requirement, we just call the parent function.
       * But if users changed text, it might not persist after optimization unless 
       * we update the parent state logic deeply. 
       * 
       * Current behavior: It optimizes the *original* prompt. The text overrides will
       * still apply to the *new* optimized prompt IF the AI preserves the original text string.
       * This is a bit risky if AI changes the text formatting.
       */

      await onOptimize(index);
    } finally {
      setOptimizingIndex(null);
    }
  };

  const handleOptimizeAllClick = async () => {
    if (isOptimizingAll || optimizingIndex !== null) return;
    const needsOptimization = prompts.some(p => (p.score || 0) < 9);
    if (!needsOptimization) return;

    setIsOptimizingAll(true);
    try {
      await onOptimizeAll();
    } finally {
      setIsOptimizingAll(false);
    }
  };

  const getScoreColor = (score: number) => {
    if (score >= 9) return 'bg-gradient-to-r from-emerald-500 to-green-500 text-white shadow-green-200';
    if (score >= 7) return 'bg-gradient-to-r from-blue-500 to-cyan-500 text-white shadow-blue-200';
    return 'bg-gradient-to-r from-orange-400 to-amber-500 text-white shadow-orange-200';
  };

  const getScoreTooltip = (score: number) => {
    if (score >= 9) return "9-10: Excellent, highly detailed and artistic";
    if (score >= 7) return "7-8: Good quality, minor improvements possible";
    if (score >= 4) return "4-6: Moderate quality, some elements missing";
    return "1-3: Basic generation, may lack detail";
  };

  const canOptimizeAny = prompts.some(p => (p.score || 0) < 9);

  return (
    <div className="w-full space-y-6">
      {/* Sticky Header Control Bar */}
      <div className="sticky top-4 z-30 bg-white/80 backdrop-blur-md rounded-2xl shadow-sm border border-gray-200/50 p-3 sm:p-4 flex flex-col md:flex-row md:items-center justify-between gap-4 transition-all duration-300">
         <div className="flex items-center gap-3">
           <div className="p-2 bg-gradient-to-br from-purple-500 to-indigo-600 rounded-xl text-white shadow-lg shadow-purple-200/50 ring-1 ring-white/20">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
              </svg>
            </div>
            <div>
                <h3 className="font-bold text-gray-800 text-lg leading-tight">Kết quả phân tích</h3>
                <p className="text-xs text-gray-500 font-medium">{prompts.length} prompt đã được tạo</p>
            </div>
         </div>

         <div className="flex flex-wrap items-center gap-2 sm:gap-3">
             <div className="relative group">
                <select
                    value={selectedFont}
                    onChange={(e) => setSelectedFont(e.target.value as FontType)}
                    className="appearance-none bg-gray-50 border border-gray-200 text-gray-600 text-xs font-bold rounded-xl pl-3 pr-8 py-2.5 leading-tight focus:outline-none focus:ring-2 focus:ring-purple-100 focus:border-purple-300 transition-colors uppercase tracking-wide cursor-pointer hover:bg-white"
                >
                    <option value="font-mono">Mono</option>
                    <option value="font-sans">Sans</option>
                    <option value="font-serif">Serif</option>
                </select>
                <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-400">
                    <svg className="h-3 w-3" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
                    </svg>
                </div>
             </div>

             {canOptimizeAny && (
                <button
                    onClick={handleOptimizeAllClick}
                    disabled={isOptimizingAll}
                    className={`flex items-center justify-center gap-2 px-3 py-2 rounded-xl text-xs font-bold transition-all duration-200 border shadow-sm
                        ${isOptimizingAll 
                        ? 'bg-purple-50 text-purple-400 border-purple-200 cursor-wait' 
                        : 'bg-gradient-to-r from-fuchsia-600 to-purple-600 text-white border-transparent hover:shadow-purple-200 hover:scale-105 active:scale-95'
                        }`}
                    title="Tối ưu hóa tất cả các prompt chưa đạt điểm tối đa"
                >
                    {isOptimizingAll ? (
                        <svg className="animate-spin h-4 w-4" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                    ) : (
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                        </svg>
                    )}
                    <span className="hidden sm:inline">{isOptimizingAll ? "Đang xử lý..." : "Tối ưu tất cả"}</span>
                </button>
             )}

             <button
                onClick={handleShare}
                className={`flex items-center justify-center gap-2 px-3 py-2 rounded-xl text-xs font-bold transition-all duration-200 border shadow-sm
                    ${shared 
                    ? 'bg-blue-50 text-blue-700 border-blue-200 ring-2 ring-blue-100' 
                    : 'bg-white text-gray-600 border-gray-200 hover:bg-blue-50 hover:text-blue-600 hover:border-blue-200'
                    }`}
                title="Chia sẻ liên kết kết quả"
             >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" />
                </svg>
                <span className="hidden sm:inline">Chia sẻ</span>
             </button>

             <button
                onClick={handleCopyAll}
                className={`flex items-center justify-center gap-2 px-3 py-2 rounded-xl text-xs font-bold transition-all duration-200 border shadow-sm
                    ${copiedAll 
                    ? 'bg-green-50 text-green-700 border-green-200 ring-2 ring-green-100' 
                    : 'bg-white text-gray-600 border-gray-200 hover:bg-green-50 hover:text-green-600 hover:border-green-200'
                    }`}
                title="Sao chép tất cả prompt"
             >
                {copiedAll ? (
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                    </svg>
                ) : (
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" />
                    </svg>
                )}
                <span className="hidden sm:inline">{copiedAll ? "Đã chép" : "Chép tất cả"}</span>
             </button>
         </div>
      </div>

      {/* Detected Text Editor Section */}
      {detectedTexts.length > 0 && (
        <div className="bg-gradient-to-r from-amber-50 to-orange-50 rounded-2xl border border-amber-100 p-5 animate-fade-in-up">
           <div className="flex items-center gap-2 mb-4">
              <div className="p-1.5 bg-amber-200 text-amber-700 rounded-lg">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M4 2a1 1 0 00-1 1v2.101a7.002 7.002 0 0111.601 2.566 1 1 0 11-1.885.666A5.002 5.002 0 005.999 7H9a1 1 0 010 2H4a1 1 0 01-1-1V3a1 1 0 011-1zm.008 9.057a1 1 0 011.276.61A5.002 5.002 0 0014.001 13H11a1 1 0 110-2h5a1 1 0 011 1v3.279a1 1 0 11-2 0V12.9a7.002 7.002 0 01-11.601-2.566 1 1 0 01.61-1.276z" clipRule="evenodd" />
                </svg>
              </div>
              <h3 className="font-bold text-amber-900 text-sm uppercase tracking-wide">Chỉnh sửa văn bản trong ảnh</h3>
