                      className="w-full px-4 py-2 rounded-xl border border-amber-200 bg-white text-gray-800 text-sm focus:ring-2 focus:ring-amber-300 focus:border-amber-400 outline-none transition-all shadow-sm"
                      placeholder={`Thay thế cho "${text}"`}
