import React, { useRef, useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { ImageFile } from '../types';

interface ImageUploaderProps {
  onImageSelected: (image: ImageFile) => void;
  onError: (message: string) => void;
  disabled?: boolean;
}

// Worker code with support for dynamic format and quality
const WORKER_CODE = `
  self.onmessage = async (e) => {
    const { file, maxDimension = 2048, quality = 0.9, outputFormat = 'image/jpeg' } = e.data;

    try {
      // Create bitmap from file
      const bitmap = await createImageBitmap(file);
      let width = bitmap.width;
      let height = bitmap.height;

      // Smart Resize
      if (width > maxDimension || height > maxDimension) {
        if (width > height) {
           height *= maxDimension / width;
           width = maxDimension;
        } else {
           width *= maxDimension / height;
           height = maxDimension;
        }
      }

      const offscreen = new OffscreenCanvas(width, height);
      const ctx = offscreen.getContext('2d');

      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = 'high';
      ctx.drawImage(bitmap, 0, 0, width, height);

      const blob = await offscreen.convertToBlob({ 
        type: outputFormat, 
        quality: quality 
      });

      const reader = new FileReader();
      reader.onloadend = () => {
        const dataUrl = reader.result;
        if (typeof dataUrl === 'string') {
            const base64 = dataUrl.split(',')[1];
            self.postMessage({ 
                success: true, 
                base64, 
                preview: dataUrl, 
                mimeType: outputFormat 
            });
        } else {
            self.postMessage({ success: false, error: 'Lỗi chuyển đổi dữ liệu ảnh.' });
        }
      };
      reader.onerror = () => {
        self.postMessage({ success: false, error: 'Không thể đọc dữ liệu file.' });
      };
      reader.readAsDataURL(blob);

    } catch (error) {
      self.postMessage({ success: false, error: error.message || 'Lỗi xử lý ảnh trong Worker.' });
    }
  };
`;

interface CompressionOptions {
  maxDimension: number;
  quality: number;
  outputFormat: string;
}

export const ImageUploader: React.FC<ImageUploaderProps> = ({ onImageSelected, onError, disabled }) => {
  const [isDragging, setIsDragging] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    if (!disabled) setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const getCompressionSettings = (file: File): CompressionOptions => {
    const isHighFidelitySource = file.type === 'image/png' || file.type === 'image/webp';
    const outputFormat = isHighFidelitySource ? 'image/webp' : 'image/jpeg';
    return {
      maxDimension: 2048, 
      quality: 0.92,
      outputFormat
    };
  };

  const compressImageFallback = (file: File, options: CompressionOptions): Promise<{ base64: string, preview: string, mimeType: string }> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onerror = () => reject(new Error("File ảnh bị lỗi hoặc không hỗ trợ."));
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const { maxDimension, quality, outputFormat } = options;

          if (width > maxDimension || height > maxDimension) {
            if (width > height) {
               height *= maxDimension / width;
               width = maxDimension;
            } else {
               width *= maxDimension / height;
               height = maxDimension;
            }
          }

          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) {
            reject(new Error("Trình duyệt không hỗ trợ Canvas 2D."));
            return;
          }
          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'high';
          ctx.drawImage(img, 0, 0, width, height);

          try {
            const dataUrl = canvas.toDataURL(outputFormat, quality);
            const base64 = dataUrl.split(',')[1];
            resolve({ base64, preview: dataUrl, mimeType: outputFormat });
          } catch (e) {
            reject(new Error("Lỗi khi nén ảnh (Fallback)."));
          }
        };
        img.src = event.target?.result as string;
      };
      reader.onerror = () => reject(new Error("Không thể đọc file."));
      reader.readAsDataURL(file);
    });
  };

  const compressImageWithWorker = (file: File): Promise<{ base64: string, preview: string, mimeType: string }> => {
    const settings = getCompressionSettings(file);
    return new Promise((resolve, reject) => {
      if (!('OffscreenCanvas' in window)) {
        compressImageFallback(file, settings).then(resolve).catch(reject);
        return;
      }

      let worker: Worker | null = null;
      const timeoutId = setTimeout(() => {
        if (worker) {
          worker.terminate();
          compressImageFallback(file, settings).then(resolve).catch(reject);
        }
      }, 8000);

      try {
        const blob = new Blob([WORKER_CODE], { type: 'application/javascript' });
        worker = new Worker(URL.createObjectURL(blob));

        worker.onmessage = (e) => {
          clearTimeout(timeoutId);
          const { success, base64, preview, mimeType, error } = e.data;
          worker?.terminate();
          if (success) resolve({ base64, preview, mimeType });
          else compressImageFallback(file, settings).then(resolve).catch(reject);
        };

        worker.onerror = (err) => {
          clearTimeout(timeoutId);
          worker?.terminate();
          compressImageFallback(file, settings).then(resolve).catch(reject);
        };

        worker.postMessage({ 
          file, 
          maxDimension: settings.maxDimension, 
          quality: settings.quality,
          outputFormat: settings.outputFormat
        });
      } catch (e) {
        clearTimeout(timeoutId);
        compressImageFallback(file, settings).then(resolve).catch(reject);
      }
    });
  };

  const processFile = async (file: File) => {
    if (!file.type.startsWith('image/')) {
      onError('Vui lòng chọn tệp hình ảnh hợp lệ (JPG, PNG, WebP).');
      return;
    }
    if (file.size === 0) {
      onError('File ảnh rỗng hoặc bị lỗi.');
      return;
    }
    setIsProcessing(true);
    try {
      const { base64, preview, mimeType } = await compressImageWithWorker(file);
      onImageSelected({ file, previewUrl: preview, base64, mimeType });
    } catch (error: any) {
      console.error("Error processing image", error);
      onError(error.message || "Có lỗi khi xử lý hình ảnh. Vui lòng thử ảnh khác.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handlePasteClick = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (disabled || isProcessing) return;
    try {
      if (!navigator.clipboard || !navigator.clipboard.read) {
        onError("Trình duyệt của bạn không hỗ trợ nút dán này. Hãy thử dùng phím tắt Ctrl+V.");
        return;
      }
      const clipboardItems = await navigator.clipboard.read();
      let found = false;
      for (const item of clipboardItems) {
        const imageType = item.types.find(type => type.startsWith('image/'));
        if (imageType) {
          const blob = await item.getType(imageType);
          const file = new File([blob], "pasted_image", { type: imageType });
          processFile(file);
          found = true;
          break;
        }
      }
      if (!found) onError("Không tìm thấy hình ảnh nào trong bộ nhớ tạm.");
    } catch (error) {
      onError("Không thể dán ảnh. Vui lòng sử dụng phím tắt Ctrl+V.");
    }
  };

  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      if (disabled || isProcessing) return;
      const items = e.clipboardData?.items;
      if (!items) return;
      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const file = items[i].getAsFile();
          if (file) {
            e.preventDefault();
            processFile(file);
            return;
          }
        }
      }
    };
    document.addEventListener('paste', handlePaste);
    return () => {
      document.removeEventListener('paste', handlePaste);
    };
  }, [disabled, isProcessing]);

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (disabled || isProcessing) return;
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      processFile(e.target.files[0]);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <motion.div
      role="button"
      tabIndex={disabled ? -1 : 0}
      aria-label="Tải ảnh lên"
      whileHover={{ scale: disabled || isProcessing ? 1 : 1.02 }}
      whileTap={{ scale: disabled || isProcessing ? 1 : 0.98 }}
      className={`relative group cursor-pointer border-3 border-dashed rounded-[2.5rem] p-10 flex flex-col items-center justify-center text-center bg-white/70 backdrop-blur-sm shadow-xl transition-all duration-300
        ${isDragging ? 'border-purple-500 bg-purple-50 scale-[1.01] shadow-2xl' : 'border-gray-300 hover:border-purple-400 hover:shadow-purple-200/50'}
        ${disabled || isProcessing ? 'opacity-70 cursor-not-allowed pointer-events-none' : ''}
      `}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      onClick={() => fileInputRef.current?.click()}
    >
      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileChange}
        accept="image/*"
        className="hidden"
        disabled={disabled || isProcessing}
      />

      {/* Animated Glow Effect on Hover */}
      <div className="absolute inset-0 rounded-[2.5rem] opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none">
         <div className="absolute inset-0 rounded-[2.5rem] bg-gradient-to-r from-purple-500/10 to-blue-500/10 blur-xl"></div>
      </div>

      {isProcessing ? (
        <div className="flex flex-col items-center animate-fade-in relative z-10">
           <div className="w-16 h-16 border-4 border-purple-200 border-t-purple-600 rounded-full animate-spin mb-4 shadow-lg"></div>
           <p className="text-purple-600 font-bold text-xl animate-pulse">Đang tối ưu hóa ảnh...</p>
           <p className="text-sm text-gray-500 mt-2 max-w-xs">
             Hệ thống đang tinh chỉnh độ phân giải và định dạng để AI phân tích tốt nhất.
           </p>
        </div>
      ) : (
        <div className="relative z-10 flex flex-col items-center">
          <motion.div 
            className="w-28 h-28 mb-6 bg-gradient-to-tr from-purple-50 to-white text-purple-600 rounded-full flex items-center justify-center shadow-lg border border-purple-100"
            animate={{ 
               y: [0, -5, 0],
               boxShadow: ["0 10px 15px -3px rgba(124, 58, 237, 0.1)", "0 20px 25px -5px rgba(124, 58, 237, 0.2)", "0 10px 15px -3px rgba(124, 58, 237, 0.1)"]
            }}
            transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 drop-shadow-sm" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
            </svg>
          </motion.div>

          <h3 className="text-3xl font-black text-gray-800 mb-3 tracking-tight">Tải ảnh lên</h3>
          <p className="text-gray-500 text-base max-w-sm mx-auto leading-relaxed mb-8">
            Kéo thả hoặc nhấp để chọn ảnh <br/>
            <span className="text-xs font-medium text-purple-500 bg-purple-50 px-2 py-0.5 rounded-full">(Hỗ trợ JPEG, PNG, WebP)</span>
          </p>

          <motion.button
            type="button"
            onClick={handlePasteClick}
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            className="relative overflow-hidden rounded-2xl bg-white px-8 py-3 text-sm font-bold text-purple-700 shadow-md ring-1 ring-purple-100 transition-all hover:shadow-xl hover:ring-purple-200"
          >
            <span className="relative z-10 flex items-center gap-2">
                <svg 
                  xmlns="http://www.w3.org/2000/svg" 
                  className="h-5 w-5" 
                  fill="none" 
                  viewBox="0 0 24 24" 
                  stroke="currentColor"
                >
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
                </svg>
                Dán từ Clipboard
            </span>
            <div className="absolute inset-0 -z-0 bg-gradient-to-r from-purple-50 to-blue-50 opacity-0 transition-opacity duration-300 hover:opacity-100" />
          </motion.button>
        </div>
      )}
    </motion.div>
  );
};

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { PromptItem } from '../types';
import { translateText } from '../services/geminiService';

interface PromptDisplayProps {
  prompts: PromptItem[];
  suggestions: string[];
  detectedTexts?: string[];
  onOptimize: (index: number) => Promise<void>;
  onOptimizeAll: () => Promise<void>;
}

type FontType = 'font-mono' | 'font-sans' | 'font-serif';

export const PromptDisplay: React.FC<PromptDisplayProps> = ({ prompts, suggestions, detectedTexts = [], onOptimize, onOptimizeAll }) => {
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);
  const [copiedAll, setCopiedAll] = useState(false);
  const [shared, setShared] = useState(false);
  const [selectedFont, setSelectedFont] = useState<FontType>('font-mono');
  const [optimizingIndex, setOptimizingIndex] = useState<number | null>(null);
  const [isOptimizingAll, setIsOptimizingAll] = useState(false);

  // State for text overrides
  const [textOverrides, setTextOverrides] = useState<Record<string, string>>({});
  const [isBatchTranslating, setIsBatchTranslating] = useState(false);

  useEffect(() => {
    const initialOverrides: Record<string, string> = {};
    detectedTexts.forEach(text => {
      initialOverrides[text] = text;
    });
    setTextOverrides(initialOverrides);
  }, [detectedTexts]);

  const handleTextOverrideChange = (original: string, newValue: string) => {
    setTextOverrides(prev => ({ ...prev, [original]: newValue }));
  };

  const handleBatchTranslate = async (targetLang: 'en' | 'vi') => {
    if (isBatchTranslating || detectedTexts.length === 0) return;
    setIsBatchTranslating(true);
    try {
        const translationPromises = detectedTexts.map(async (original) => {
             const currentText = textOverrides[original] || original;
             try {
                 const translated = await translateText(currentText, targetLang);
                 return { original, translated };
             } catch (e) {
                 return { original, translated: currentText };
             }
        });
        const results = await Promise.all(translationPromises);
        const newOverrides = { ...textOverrides };
        results.forEach(({ original, translated }) => {
            newOverrides[original] = translated;
        });
        setTextOverrides(newOverrides);
    } catch (error) {
        console.error("Batch translation failed", error);
    } finally {
        setIsBatchTranslating(false);
    }
  };

  const getDisplayPrompt = (originalPromptText: string): string => {
    let finalPrompt = originalPromptText;
    detectedTexts.forEach(original => {
      const replacement = textOverrides[original];
      if (replacement && replacement !== original) {
        finalPrompt = finalPrompt.split(original).join(replacement);
      }
    });
    return finalPrompt;
  };

  const handleCopy = async (text: string, index: number) => {
    try {
      const textToCopy = getDisplayPrompt(text);
      await navigator.clipboard.writeText(textToCopy);
      setCopiedIndex(index);
      setTimeout(() => setCopiedIndex(null), 2000);
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  const handleCopyAll = async () => {
    try {
      const allText = prompts.map(p => getDisplayPrompt(p.text)).join('\n\n');
      await navigator.clipboard.writeText(allText);
      setCopiedAll(true);
      setTimeout(() => setCopiedAll(false), 2000);
    } catch (err) {
      console.error('Failed to copy all text: ', err);
    }
  };

  const handleShare = async () => {
    try {
      const shareData = {
        p: prompts,
        s: suggestions,
        t: detectedTexts
      };
      const jsonString = JSON.stringify(shareData);
      const encoded = btoa(unescape(encodeURIComponent(jsonString)));
      const url = new URL(window.location.href);
      url.searchParams.set('share', encoded);
      const shareUrl = url.toString();
      await navigator.clipboard.writeText(shareUrl);
      window.history.pushState({}, '', shareUrl);
      setShared(true);
      setTimeout(() => setShared(false), 2000);
    } catch (err) {
      console.error('Failed to generate share link: ', err);
    }
  };

  const handleUsePrompt = (text: string, index: number) => {
      handleCopy(text, index);
      window.open('https://labs.google/fx/tools/whisk/project', '_blank');
  };

  const handleOptimizeClick = async (index: number) => {
    if (optimizingIndex !== null || isOptimizingAll) return;
    setOptimizingIndex(index);
    try {
      await onOptimize(index);
    } finally {
      setOptimizingIndex(null);
    }
  };

  const handleOptimizeAllClick = async () => {
    if (isOptimizingAll || optimizingIndex !== null) return;
    const needsOptimization = prompts.some(p => (p.score || 0) < 10);
    if (!needsOptimization) return;

    setIsOptimizingAll(true);
    try {
      await onOptimizeAll();
    } finally {
      setIsOptimizingAll(false);
    }
  };

  const getScoreColor = (score: number) => {
    if (score >= 9) return 'bg-gradient-to-r from-emerald-500 to-green-500 text-white shadow-green-200';
    if (score >= 7) return 'bg-gradient-to-r from-blue-500 to-cyan-500 text-white shadow-blue-200';
    return 'bg-gradient-to-r from-orange-400 to-amber-500 text-white shadow-orange-200';
  };

  const getScoreTooltip = (score: number) => {
    if (score >= 9) return "9-10: Excellent, highly detailed and artistic";
    if (score >= 7) return "7-8: Good quality, minor improvements possible";
    if (score >= 4) return "4-6: Moderate quality, some elements missing";
    return "1-3: Basic generation, may lack detail";
  };

  const canOptimizeAny = prompts.some(p => (p.score || 0) < 10);

  // Framer Motion Variants
  const containerVariants = {
    hidden: { opacity: 0 },
    show: {
      opacity: 1,
      transition: {
        staggerChildren: 0.15
      }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 50, scale: 0.9 },
    show: { opacity: 1, y: 0, scale: 1, transition: { type: 'spring', stiffness: 100 } }
  };

  return (
    <div className="w-full space-y-6">
      {/* Sticky Header Control Bar */}
      <motion.div 
        initial={{ y: -20, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        className="sticky top-4 z-30 bg-white/80 backdrop-blur-md rounded-2xl shadow-lg border border-gray-200/50 p-3 sm:p-4 flex flex-col md:flex-row md:items-center justify-between gap-4 transition-all duration-300"
      >
         <div className="flex items-center gap-3">
           <div className="p-2 bg-gradient-to-br from-purple-500 to-indigo-600 rounded-xl text-white shadow-lg shadow-purple-200/50 ring-1 ring-white/20">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
              </svg>
            </div>
            <div>
                <h3 className="font-bold text-gray-800 text-lg leading-tight">Kết quả phân tích</h3>
                <p className="text-xs text-gray-500 font-medium">{prompts.length} prompt đã được tạo</p>
            </div>
         </div>

         <div className="flex flex-wrap items-center gap-2 sm:gap-3">
             <div className="relative group">
                <select
                    value={selectedFont}
                    onChange={(e) => setSelectedFont(e.target.value as FontType)}
                    className="appearance-none bg-gray-50 border border-gray-200 text-gray-600 text-xs font-bold rounded-xl pl-3 pr-8 py-2.5 leading-tight focus:outline-none focus:ring-2 focus:ring-purple-100 focus:border-purple-300 transition-colors uppercase tracking-wide cursor-pointer hover:bg-white"
                >
                    <option value="font-mono">Mono</option>
                    <option value="font-sans">Sans</option>
                    <option value="font-serif">Serif</option>
                </select>
                <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-400">
                    <svg className="h-3 w-3" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
                    </svg>
                </div>
             </div>

             {canOptimizeAny && (
                <motion.button
                    onClick={handleOptimizeAllClick}
                    disabled={isOptimizingAll}
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                    className={`flex items-center justify-center gap-2 px-3 py-2 rounded-xl text-xs font-bold transition-all duration-200 border shadow-sm
                        ${isOptimizingAll 
                        ? 'bg-purple-50 text-purple-400 border-purple-200 cursor-wait' 
                        : 'bg-gradient-to-r from-fuchsia-600 to-purple-600 text-white border-transparent hover:shadow-purple-200'
                        }`}
                >
                    {isOptimizingAll ? (
                        <svg className="animate-spin h-4 w-4" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                    ) : (
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                        </svg>
                    )}
                    <span className="hidden sm:inline">{isOptimizingAll ? "Đang xử lý..." : "Tối ưu tất cả"}</span>
                </motion.button>
             )}

             <motion.button
                onClick={handleShare}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                className={`flex items-center justify-center gap-2 px-3 py-2 rounded-xl text-xs font-bold transition-all duration-200 border shadow-sm
                    ${shared 
                    ? 'bg-blue-50 text-blue-700 border-blue-200 ring-2 ring-blue-100' 
                    : 'bg-white text-gray-600 border-gray-200 hover:bg-blue-50 hover:text-blue-600 hover:border-blue-200'
                    }`}
             >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" />
                </svg>
                <span className="hidden sm:inline">Chia sẻ</span>
             </motion.button>

             <motion.button
                onClick={handleCopyAll}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                className={`flex items-center justify-center gap-2 px-3 py-2 rounded-xl text-xs font-bold transition-all duration-200 border shadow-sm
                    ${copiedAll 
                    ? 'bg-green-50 text-green-700 border-green-200 ring-2 ring-green-100' 
                    : 'bg-white text-gray-600 border-gray-200 hover:bg-green-50 hover:text-green-600 hover:border-green-200'
                    }`}
             >
                {copiedAll ? (
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                    </svg>
                ) : (
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" />
                    </svg>
                )}
                <span className="hidden sm:inline">{copiedAll ? "Đã chép" : "Chép tất cả"}</span>
             </motion.button>
         </div>
      </motion.div>

      {/* Detected Text Editor Section */}
      <AnimatePresence>
      {detectedTexts.length > 0 && (
        <motion.div 
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="bg-gradient-to-r from-amber-50 to-orange-50 rounded-2xl border border-amber-100 p-5 shadow-sm"
        >
           <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-5">
               <div className="flex items-center gap-2">
                  <div className="p-1.5 bg-amber-200 text-amber-700 rounded-lg">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M4 2a1 1 0 00-1 1v2.101a7.002 7.002 0 0111.601 2.566 1 1 0 11-1.885.666A5.002 5.002 0 005.999 7H9a1 1 0 010 2H4a1 1 0 01-1-1V3a1 1 0 011-1zm.008 9.057a1 1 0 011.276.61A5.002 5.002 0 0014.001 13H11a1 1 0 110-2h5a1 1 0 011 1v3.279a1 1 0 11-2 0V12.9a7.002 7.002 0 01-11.601-2.566 1 1 0 01.61-1.276z" clipRule="evenodd" />
                    </svg>
                  </div>
                  <div>
                      <h3 className="font-bold text-amber-900 text-sm uppercase tracking-wide">Chỉnh sửa văn bản trong ảnh</h3>
                      <p className="text-[10px] text-amber-600/70 italic">* Thay đổi ở đây sẽ tự động cập nhật vào prompt</p>
                  </div>
               </div>

               <div className="flex gap-2">
                   {/* Translation buttons */}
                   <motion.button
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                      onClick={() => handleBatchTranslate('en')}
                      disabled={isBatchTranslating}
                      className="flex items-center gap-2 px-3 py-1.5 text-xs font-bold uppercase tracking-wide rounded-lg bg-indigo-50 text-indigo-700 hover:bg-indigo-100 border border-indigo-200 transition-all disabled:opacity-50 shadow-sm"
                   >
                      {isBatchTranslating ? (
                          <svg className="animate-spin h-3.5 w-3.5" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                      ) : (
                          <span>🇺🇸</span>
                      )}
                      <span>Dịch tất cả sang Anh</span>
                   </motion.button>
                   <motion.button
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                      onClick={() => handleBatchTranslate('vi')}
                      disabled={isBatchTranslating}
                      className="flex items-center gap-2 px-3 py-1.5 text-xs font-bold uppercase tracking-wide rounded-lg bg-red-50 text-red-700 hover:bg-red-100 border border-red-200 transition-all disabled:opacity-50 shadow-sm"
                   >
                      {isBatchTranslating ? (
                          <svg className="animate-spin h-3.5 w-3.5" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                      ) : (
                          <span>🇻🇳</span>
                      )}
                      <span>Dịch tất cả sang Việt</span>
                   </motion.button>
               </div>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {detectedTexts.map((text, idx) => {
                return (
                  <div key={idx} className="flex flex-col gap-1.5 bg-white/50 p-3 rounded-xl border border-amber-100 hover:border-amber-200 transition-colors">
                     <label className="text-xs font-semibold text-amber-700 ml-1 truncate" title={text}>
                        Gốc: "{text}"
                     </label>
                     <div className="relative">
                       <input 
                          type="text" 
                          value={textOverrides[text] || text}
                          onChange={(e) => handleTextOverrideChange(text, e.target.value)}
                          className="w-full pl-4 pr-4 py-2 rounded-xl border border-amber-200 bg-white text-gray-800 text-sm focus:ring-2 focus:ring-amber-300 focus:border-amber-400 outline-none transition-all shadow-sm"
                          placeholder={`Thay thế cho "${text}"`}
                       />
                     </div>
                  </div>
                );
              })}
           </div>
        </motion.div>
      )}
      </AnimatePresence>

      {/* Prompts Grid with Staggered Animation */}
      <motion.div 
        variants={containerVariants}
        initial="hidden"
        animate="show"
        className="grid grid-cols-1 lg:grid-cols-2 gap-6"
      >
        {prompts.map((promptItem, index) => {
          const isMain = index === 0;
          const displayPromptText = getDisplayPrompt(promptItem.text);

          return (
            <motion.div 
              key={index} 
              variants={itemVariants}
              whileHover={{ y: -5, transition: { duration: 0.2 } }}
              className={`group flex flex-col bg-white rounded-[2rem] shadow-sm border border-gray-100 overflow-hidden relative
                ${isMain ? 'lg:col-span-2 ring-1 ring-purple-100 shadow-purple-50' : ''}
              `}
            >
              {/* Sheen Effect on Hover */}
              <div className="absolute top-0 -inset-full h-full w-1/2 z-5 block transform -skew-x-12 bg-gradient-to-r from-transparent to-white opacity-20 group-hover:animate-shine" />

              {/* Card Header */}
              <div className={`px-6 py-4 border-b border-gray-100 flex items-center justify-between
                 ${isMain 
                    ? 'bg-gradient-to-r from-purple-50/50 via-white to-blue-50/50' 
                    : 'bg-gradient-to-r from-gray-50/50 to-white'}
              `}>
                 <div className="flex items-center gap-3">
                    <span className={`flex items-center justify-center w-8 h-8 rounded-full text-sm font-bold shadow-sm ring-1 ring-white
                        ${isMain ? 'bg-purple-600 text-white shadow-purple-200' : 'bg-white text-gray-500 border border-gray-200'}`}>
                        {index + 1}
                    </span>
                    <div className="flex flex-col">
                        <div className="flex items-center gap-2">
                            <span className={`font-bold text-sm ${isMain ? 'text-purple-900' : 'text-gray-700'}`}>
                                {isMain ? "Bản Sao Hoàn Hảo" : `Biến Thể ${index}`}
                            </span>
                            {(promptItem.score !== undefined) && (
                                <span 
                                  className={`px-2 py-0.5 rounded-md text-[10px] font-bold shadow-sm cursor-help ${getScoreColor(promptItem.score)}`}
                                  title={getScoreTooltip(promptItem.score)}
                                >
                                    {promptItem.score}/10
                                </span>
                            )}
                        </div>
                        {isMain ? (
                             <span className="text-[10px] font-semibold text-purple-600 uppercase tracking-wider">
                                 High Fidelity Replication
                             </span>
                        ) : (
                             <span className="text-[10px] font-medium text-gray-400 tracking-wide">
                                 Same style, different pose
                             </span>
                        )}
                    </div>
                 </div>

                 <div className="flex items-center gap-2">
                     {(promptItem.score || 0) < 9 && (
                         <motion.button
                            whileHover={{ scale: 1.05 }}
                            whileTap={{ scale: 0.95 }}
                            onClick={() => handleOptimizeClick(index)}
                            disabled={optimizingIndex === index || isOptimizingAll}
                            className={`p-2 rounded-xl transition-all duration-200 border flex items-center gap-2
                                ${optimizingIndex === index 
                                    ? 'bg-purple-50 text-purple-400 border-purple-100 cursor-wait'
                                    : 'bg-white text-purple-600 border-purple-100 hover:bg-purple-600 hover:text-white shadow-sm hover:shadow-purple-200'
                                }`}
                         >
                            {optimizingIndex === index ? (
                                 <svg className="animate-spin h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
