                      disabled={promptCount <= 1}
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" />
                      </svg>
                    </button>
                    <input
                      type="number"
                      min="1"
                      value={promptCount}
                      onChange={(e) => {
                        const val = parseInt(e.target.value);
                        if (!isNaN(val) && val > 0) {
                          setPromptCount(val);
                        }
                      }}
                      className="w-12 text-center font-black text-xl text-gray-700 bg-transparent outline-none appearance-none"
                      aria-label="Nhập số lượng prompt"
                    />
                    <button 
                      onClick={() => setPromptCount(promptCount + 1)}
                      className="w-10 h-10 flex items-center justify-center rounded-full bg-white text-gray-500 shadow-md hover:bg-gray-100 hover:text-pink-500 transition-all"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" />
                      </svg>
                    </button>
                  </div>
                </div>

                <div className="transform transition-all duration-500 hover:-translate-y-1">
                  <ImageUploader onImageSelected={handleImageSelected} onError={handleError} />
                </div>

                {/* Home View Error Display (e.g. upload failed) */}
                {appState === AppState.ERROR && errorDetails && !image && (
                   <motion.div 
                    initial={{ opacity: 0, height: 0 }}
                    animate={{ opacity: 1, height: 'auto' }}
                    className="bg-red-50 border-2 border-red-100 rounded-[2rem] p-6 flex flex-col gap-3 shadow-sm"
                   >
                      <div className="flex items-start gap-3">
                        <div className="p-3 bg-red-100 rounded-full text-red-600 shrink-0">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                            </svg>
                        </div>
                        <div>
                            <h3 className="text-lg font-black text-gray-800">{errorDetails.title}</h3>
                            <p className="text-gray-600 mt-1 font-medium">{errorDetails.message}</p>
                        </div>
                      </div>

                      {/* Suggestion list for home error */}
                      <div className="pl-14">
                        <ul className="list-disc pl-5 space-y-1 text-sm text-gray-500 font-medium">
                             {errorDetails.suggestions.map((s, i) => <li key={i}>{s}</li>)}
                        </ul>
                      </div>
                   </motion.div>
                )}

                <HistoryList 
                  history={history} 
                  onSelect={handleSelectHistory} 
                  onClear={handleClearHistory} 
                />
              </motion.div>
            ) : (
              <motion.div
                key="results"
                initial={{ opacity: 0, y: 30 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                transition={{ duration: 0.3, ease: "easeOut" }}
                className="flex flex-col gap-10"
              >
                {/* Top: Image Preview or Shared Placeholder */}
                <div className="w-full max-w-lg mx-auto flex flex-col gap-6">
                  {image ? (
                      <div className="bg-white rounded-[2.5rem] p-3 shadow-xl border-4 border-white group relative overflow-hidden">
                      <div className="aspect-square rounded-[2rem] overflow-hidden bg-gray-100 relative shadow-inner">
                          <img 
                          src={image.previewUrl} 
                          alt="Uploaded preview" 
                          className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
                          />

                          {appState !== AppState.ANALYZING && (
                          <button 
                              onClick={handleReset}
                              className="absolute top-4 right-4 bg-white/90 hover:bg-red-50 text-gray-400 hover:text-red-500 p-2.5 rounded-full shadow-lg backdrop-blur-sm transition-all transform hover:rotate-90 z-10 border-2 border-white"
                              title="Xóa ảnh"
                          >
                              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" />
                              </svg>
                          </button>
                          )}

                          {appState !== AppState.ANALYZING && (
                          <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-center justify-center backdrop-blur-[2px]">
                              <button 
                              onClick={handleReset}
                              className="bg-white text-gray-800 px-8 py-3 rounded-full text-base font-extrabold shadow-2xl hover:bg-gray-50 transition-all transform hover:scale-105"
                              >
                              Chọn ảnh khác
                              </button>
                          </div>
                          )}
                      </div>
                      </div>
                  ) : (
                      /* Shared View Placeholder */
                     !image && isSharedMode && (
                          <div className="bg-white rounded-[2.5rem] p-8 text-center border-4 border-white shadow-xl animate-fade-in flex flex-col items-center gap-4">
                              <div className="w-24 h-24 bg-purple-100 text-purple-500 rounded-full flex items-center justify-center shadow-inner border-4 border-purple-50">
                                  <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" />
                                  </svg>
                              </div>
                              <div>
                                  <h3 className="text-xl font-black text-gray-800 mb-2">Kết quả được chia sẻ</h3>
                                  <p className="text-gray-500 text-sm max-w-xs mx-auto font-medium">
                                      Bạn đang xem prompt từ liên kết chia sẻ. Hình ảnh gốc không được lưu trữ trong liên kết này.
                                  </p>
                              </div>
                              <button 
                                  onClick={handleReset}
                                  className="mt-4 bg-purple-500 text-white px-8 py-3 rounded-full font-bold hover:bg-purple-600 transition-colors shadow-lg shadow-purple-200 hover:shadow-xl active:scale-95"
                              >
                                  Tạo prompt mới của bạn
                              </button>
                          </div>
                     )
                  )}

                   {/* Main Results View Error Display */}
                   {appState === AppState.ERROR && errorDetails && (
                      <ErrorDisplay details={errorDetails} />
                   )}
                </div>

                {/* Bottom: Results or Loading */}
                <div className="w-full" ref={resultsRef}>
                   {/* IDLE state placeholder removed as we usually jump to analyzing immediately */}

                   {appState === AppState.ANALYZING && <SkeletonLoader />}

                   {appState === AppState.SUCCESS && analysisResult && (
                     <div className="flex flex-col gap-6">
                       <PromptDisplay 
                          prompts={analysisResult.prompts} 
                          suggestions={analysisResult.suggestions}
                          detectedTexts={analysisResult.detectedTexts}
                          onOptimize={handleOptimize}
                          onOptimizeAll={handleOptimizeAll}
                       />
                       <SuggestionsDisplay suggestions={analysisResult.suggestions} />
                       <WhiskGuide />
                       <button 
                          onClick={handleReset} 
                          className="md:hidden w-full py-4 bg-white border-2 border-gray-100 text-gray-500 rounded-full font-bold shadow-sm active:bg-gray-50 uppercase tracking-wide"
                        >
                          Giải mã ảnh khác
                        </button>
                     </div>
                   )}
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>

      {/* Enhanced Footer */}
      <footer className="py-8 border-t border-white/50 bg-white/40 backdrop-blur-md mt-auto">
        <div className="max-w-5xl mx-auto px-4 text-center">
          <p className="text-gray-400 text-xs font-bold">@2025 Trợ Lý Bé Điệu ✨</p>
        </div>
      </footer>

      {/* Scroll to Top Button */}
      {showScrollTop && (
        <button
          onClick={scrollToTop}
          className="fixed bottom-8 right-8 z-50 p-4 bg-white/90 backdrop-blur-md border-2 border-pink-200 text-pink-500 rounded-full shadow-lg hover:bg-pink-500 hover:text-white hover:shadow-pink-300 transition-all duration-300 transform hover:scale-110 active:scale-95 animate-fade-in"
          aria-label="Cuộn lên đầu trang"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 10l7-7m0 0l7 7m-7-7v18" />
          </svg>
        </button>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { PromptItem } from '../types';
import { translateText } from '../services/geminiService';

interface PromptDisplayProps {
  prompts: PromptItem[];
  suggestions: string[];
  detectedTexts?: string[];
  onOptimize: (index: number) => Promise<void>;
  onOptimizeAll: () => Promise<void>;
}

type FontType = 'font-mono' | 'font-sans' | 'font-serif';

export const PromptDisplay: React.FC<PromptDisplayProps> = ({ prompts, suggestions, detectedTexts = [], onOptimize, onOptimizeAll }) => {
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);
  const [copiedAll, setCopiedAll] = useState(false);
  const [shared, setShared] = useState(false);
  const [selectedFont, setSelectedFont] = useState<FontType>('font-mono');
  const [optimizingIndex, setOptimizingIndex] = useState<number | null>(null);
  const [isOptimizingAll, setIsOptimizingAll] = useState(false);

  // State for text overrides
  const [textOverrides, setTextOverrides] = useState<Record<string, string>>({});
  const [isBatchTranslating, setIsBatchTranslating] = useState(false);

  useEffect(() => {
    const initialOverrides: Record<string, string> = {};
    detectedTexts.forEach(text => {
      initialOverrides[text] = text;
    });
    setTextOverrides(initialOverrides);
  }, [detectedTexts]);

  const handleTextOverrideChange = (original: string, newValue: string) => {
    setTextOverrides(prev => ({ ...prev, [original]: newValue }));
  };

  const handleBatchTranslate = async (targetLang: 'en' | 'vi') => {
    if (isBatchTranslating || detectedTexts.length === 0) return;
    setIsBatchTranslating(true);
    try {
        const translationPromises = detectedTexts.map(async (original) => {
             const currentText = textOverrides[original] || original;
             try {
                 const translated = await translateText(currentText, targetLang);
                 return { original, translated };
             } catch (e) {
                 return { original, translated: currentText };
             }
        });
        const results = await Promise.all(translationPromises);
        const newOverrides = { ...textOverrides };
        results.forEach(({ original, translated }) => {
            newOverrides[original] = translated;
        });
        setTextOverrides(newOverrides);
    } catch (error) {
        console.error("Batch translation failed", error);
    } finally {
        setIsBatchTranslating(false);
    }
  };

  const getDisplayPrompt = (originalPromptText: string): string => {
    let finalPrompt = originalPromptText;
    detectedTexts.forEach(original => {
      const replacement = textOverrides[original];
      if (replacement && replacement !== original) {
        finalPrompt = finalPrompt.split(original).join(replacement);
      }
    });
    return finalPrompt;
  };

  const handleCopy = async (text: string, index: number) => {
    try {
      const textToCopy = getDisplayPrompt(text);
      await navigator.clipboard.writeText(textToCopy);
      setCopiedIndex(index);
      setTimeout(() => setCopiedIndex(null), 2000);
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  const handleCopyAll = async () => {
    try {
      const allText = prompts.map(p => getDisplayPrompt(p.text)).join('\n\n');
      await navigator.clipboard.writeText(allText);
      setCopiedAll(true);
      setTimeout(() => setCopiedAll(false), 2000);
    } catch (err) {
      console.error('Failed to copy all text: ', err);
    }
  };

  const handleShare = async () => {
    try {
      const shareData = {
        p: prompts,
        s: suggestions,
        t: detectedTexts
      };
      const jsonString = JSON.stringify(shareData);
      const encoded = btoa(unescape(encodeURIComponent(jsonString)));
      const url = new URL(window.location.href);
      url.searchParams.set('share', encoded);
      const shareUrl = url.toString();
      await navigator.clipboard.writeText(shareUrl);
      window.history.pushState({}, '', shareUrl);
      setShared(true);
      setTimeout(() => setShared(false), 2000);
    } catch (err) {
      console.error('Failed to generate share link: ', err);
    }
  };

  const handleUsePrompt = (text: string, index: number) => {
      handleCopy(text, index);
      window.open('https://labs.google/fx/tools/whisk/project', '_blank');
  };

  const handleOptimizeClick = async (index: number) => {
    if (optimizingIndex !== null || isOptimizingAll) return;
    setOptimizingIndex(index);
    try {
      await onOptimize(index);
    } finally {
      setOptimizingIndex(null);
    }
  };

  const handleOptimizeAllClick = async () => {
    if (isOptimizingAll || optimizingIndex !== null) return;
    const needsOptimization = prompts.some(p => (p.score || 0) < 10);
    if (!needsOptimization) return;

    setIsOptimizingAll(true);
    try {
      await onOptimizeAll();
    } finally {
      setIsOptimizingAll(false);
    }
  };

  const getScoreColor = (score: number) => {
    if (score >= 9) return 'bg-pink-100 text-pink-600 border border-pink-200';
    if (score >= 7) return 'bg-blue-100 text-blue-600 border border-blue-200';
    return 'bg-yellow-100 text-yellow-600 border border-yellow-200';
  };

  const getScoreTooltip = (score: number) => {
    if (score >= 9) return "Chất lượng tuyệt vời: Chi tiết và chính xác cao";
    if (score >= 7) return "Chất lượng tốt: Đầy đủ các yếu tố chính";
    return "Chất lượng trung bình: Có thể cần bổ sung thêm chi tiết";
  };

  const canOptimizeAny = prompts.some(p => (p.score || 0) < 10);

  // Framer Motion Variants
  const containerVariants = {
    hidden: { opacity: 0 },
    show: {
      opacity: 1,
      transition: {
        staggerChildren: 0.15
      }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 50, scale: 0.9 },
    show: { opacity: 1, y: 0, scale: 1, transition: { type: 'spring', stiffness: 100 } }
  };

  // Reusable Kawaii Button Style
  const KawaiiButton = ({ color, onClick, disabled, children, active }: any) => {
    const colors: any = {
      pink: "from-pink-300 to-rose-300 shadow-pink-200 text-white border-pink-100",
      blue: "from-sky-300 to-blue-300 shadow-sky-200 text-white border-sky-100",
      yellow: "from-amber-200 to-orange-300 shadow-orange-100 text-white border-yellow-50",
      white: "from-white to-gray-50 shadow-gray-200 text-gray-600 border-gray-100 hover:text-pink-500",
      active: "from-green-400 to-emerald-400 shadow-green-200 text-white border-green-200"
    };

    const bgClass = active ? colors.active : colors[color];

    return (
      <motion.button
        onClick={onClick}
        disabled={disabled}
        whileHover={{ scale: 1.05, translateY: -2 }}
        whileTap={{ scale: 0.95 }}
        className={`
          relative flex items-center justify-center gap-2 px-4 py-2.5 rounded-full
          bg-gradient-to-b ${bgClass}
          shadow-[0_4px_10px_-2px] hover:shadow-[0_6px_15px_-3px]
          border-t-2 transition-all duration-300
          text-sm font-extrabold tracking-wide uppercase
          ${disabled ? 'opacity-70 cursor-wait grayscale' : ''}
        `}
      >
        {children}
        {/* Shine effect */}
        <div className="absolute top-0 left-0 w-full h-1/2 bg-white/20 rounded-t-full pointer-events-none" />
      </motion.button>
    );
  };

  return (
    <div className="w-full space-y-6">
      {/* Sticky Header Control Bar */}
      <motion.div 
        initial={{ y: -20, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        className="sticky top-4 z-30 bg-white/85 backdrop-blur-lg rounded-[2rem] shadow-xl shadow-purple-500/5 border-2 border-white p-3 sm:p-4 flex flex-col md:flex-row md:items-center justify-between gap-4 transition-all duration-300"
      >
         <div className="flex items-center gap-3">
           <div className="p-3 bg-pink-100 rounded-full text-pink-500 border-2 border-white shadow-md">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
              </svg>
            </div>
            <div>
                <h3 className="font-black text-gray-700 text-lg leading-tight">Kết quả phân tích</h3>
                <p className="text-xs text-gray-400 font-bold">{prompts.length} prompt đã được tạo</p>
            </div>
         </div>

         <div className="flex flex-wrap items-center gap-2 sm:gap-3">
             <div className="relative group">
                <select
                    value={selectedFont}
                    onChange={(e) => setSelectedFont(e.target.value as FontType)}
                    className="appearance-none bg-gray-50 border-2 border-gray-100 text-gray-600 text-xs font-bold rounded-full pl-4 pr-10 py-2.5 outline-none focus:border-pink-300 transition-colors uppercase tracking-wide cursor-pointer hover:bg-white shadow-sm"
                >
                    <option value="font-mono">Mono</option>
                    <option value="font-sans">Sans</option>
                    <option value="font-serif">Serif</option>
                </select>
                <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-3 text-gray-400">
                    <svg className="h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
                    </svg>
                </div>
             </div>

             {canOptimizeAny && (
                <KawaiiButton color="yellow" onClick={handleOptimizeAllClick} disabled={isOptimizingAll}>
                    {isOptimizingAll ? (
                        <svg className="animate-spin h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                    ) : (
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                        </svg>
                    )}
                    <span className="hidden sm:inline">{isOptimizingAll ? "Đang xử lý" : "Tối ưu hết"}</span>
                </KawaiiButton>
             )}

             <KawaiiButton color="blue" onClick={handleShare} active={shared}>
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" />
                </svg>
                <span className="hidden sm:inline">Chia sẻ</span>
             </KawaiiButton>

             <KawaiiButton color="pink" onClick={handleCopyAll} active={copiedAll}>
                {copiedAll ? (
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                    </svg>
                ) : (
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" />
                    </svg>
                )}
                <span className="hidden sm:inline">{copiedAll ? "Đã chép!" : "Chép hết"}</span>
             </KawaiiButton>
         </div>
      </motion.div>

      {/* Detected Text Editor Section */}
      <AnimatePresence>
      {detectedTexts.length > 0 && (
        <motion.div 
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="bg-orange-50 rounded-[2rem] border-2 border-orange-100 p-6 shadow-sm"
        >
