                     </MotionButton>
                 </div>
              </div>

              {/* Card Body */}
              <div className="flex-grow p-6 bg-white cursor-text">
                <p className={`${selectedFont} text-sm font-medium leading-7 text-gray-600 whitespace-pre-wrap selection:bg-pink-100 selection:text-pink-900`}>
                    {displayPromptText}
