const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key chưa được cấu hình trong hệ thống. Vui lòng kiểm tra biến môi trường.");
  }
  return new GoogleGenAI({ apiKey });
};

// Helper function to pause execution
export const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Generic retry wrapper for API calls
const retryOperation = async <T>(
  operation: () => Promise<T>, 
  retries: number = 3, 
  baseDelay: number = 2000
): Promise<T> => {
  let lastError: any;

  for (let i = 0; i < retries; i++) {
    try {
      return await operation();
    } catch (error: any) {
      lastError = error;
      const errorMessage = (error.message || JSON.stringify(error)).toLowerCase();

      // Identify retryable errors
      const isRateLimit = errorMessage.includes('429') || errorMessage.includes('resource exhausted') || errorMessage.includes('quota');
      const isNetwork = 
        errorMessage.includes('500') || 
        errorMessage.includes('503') || 
        errorMessage.includes('fetch failed') ||
        errorMessage.includes('network error') ||
        errorMessage.includes('overloaded');

      if ((!isRateLimit && !isNetwork) || i === retries - 1) {
        throw error;
      }

      // Exponential backoff: Wait longer if it's a rate limit error
      // Attempt 1: 2000ms (Network) / 4000ms (RateLimit)
      // Attempt 2: 4000ms / 9000ms
      // Attempt 3: 8000ms / 19000ms
      const delay = isRateLimit 
        ? (baseDelay * Math.pow(2, i)) + 2000 
        : baseDelay * Math.pow(2, i);

      console.warn(`Gemini API retry attempt ${i + 1}/${retries} after ${delay}ms. Reason: ${isRateLimit ? 'Rate Limit' : 'Network/Server'}`);
      await wait(delay);
    }
  }

  throw lastError;
};

export const decodeImagePrompt = async (base64Data: string, mimeType: string, count: number = 1): Promise<AnalysisResult> => {
  try {
    const ai = getClient();

    const imagePart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Data
      }
    };

    const promptText = `
      You are a world-class Art Director, Fashion Analyst, and Visual Reconstruction Expert.

      GOAL:
      Analyze the given image and generate ultra-precise, fashion-editorial-grade prompts to perfectly replicate and vary the image while maintaining absolute subject consistency.

      ––––––––––––––––––––––
      1. DETAILED VISUAL BREAKDOWN (EXTREME PRECISION)

      Analyze the image in the following order and depth:

      A. Jewelry & Accessories (CRITICAL – DO NOT GENERALIZE)
      - Earrings: type, size, shape, metal, gemstones, finish
      - Necklaces: chain type, length, pendant details
      - Rings: finger placement, metal, stone cut
      - Watches / Bracelets: brand style, material, dial
      - Bags, glasses, hats, belts (if any)
      → Describe materials precisely (gold vs champagne gold, polished vs brushed, leather grain, etc.)

      B. Outfit & Garment Construction
      - Fabric type and texture (silk satin, wool twill, ribbed knit, sheer chiffon…)
      - Tailoring: silhouette, fit, seams, darts, shoulder structure
      - Color accuracy (use professional color terms)
      - Layering and garment interaction
      - Wrinkles, folds, tension points

      C. Subject Description (LOCK IDENTITY)
      - Gender presentation, body proportions
      - Hairstyle, parting, length, texture
      - Makeup: skin finish, eye makeup, lips, contour
      - Facial expression and emotion

      D. Context & Environment
      - Location type (studio / indoor / outdoor / architectural)
      - Background elements and materials
      - Depth, negative space, composition balance

      E. Lighting & Color Science
      - Light direction (key, fill, rim)
      - Light quality (soft diffused / hard directional)
      - Color temperature (warm / neutral / cool)
      - Mood (editorial, cinematic, luxury, minimal)

      ––––––––––––––––––––––
      2. PROMPT GENERATION STRATEGY

      Generate ${count} prompts in total:

      PROMPT #1 – REPLICA (ABSOLUTE MATCH)
      - **MANDATORY START**: Begin the prompt exactly with: "Create a highly realistic studio portrait of the woman from the uploaded photo, ensuring her face is 99.99% identical to the reference."
      - 100% identical subject, outfit, accessories, makeup, hair
      - Same camera angle, framing, focal length
      - Same pose and facial expression
      - Same lighting and mood
      → This prompt must reproduce the original image as accurately as possible.

      PROMPT #2 → #${count} – VARIATIONS (CONTROLLED ARTISTIC VIEWS)
      STRICT RULES:
      - Subject identity MUST remain the same (Use the mandatory phrase: "Create a highly realistic studio portrait of the woman from the uploaded photo, ensuring her face is 99.99% identical to the reference.")
      - Outfit, jewelry, accessories MUST remain identical
      - Environment and styling MUST remain identical

      ONLY change:
      - Camera angle (e.g. low angle, 3/4 profile, over-the-shoulder)
      - Focal length (e.g. 35mm, 50mm, 85mm)
      - Body pose and micro-expression (fashion editorial poses)

      ––––––––––––––––––––––
      3. PROMPT FORMAT REQUIREMENTS

      - Language: English
      - Style: Midjourney v6 / Flux optimized
      - Use professional photography & fashion vocabulary
      - Highly descriptive, no ambiguity
      - No storytelling, no assumptions

      ––––––––––––––––––––––
      4. OUTPUT FORMAT (JSON ONLY – NO EXTRA TEXT)

      {
        "prompts": [
          {
            "text": "Full English prompt here",
            "score": 1-10 (detail & accuracy rating)
          }
        ],
        "detectedTexts": [
          "Any visible text found in the image"
        ],
        "suggestions": [
          "3–5 Vietnamese suggestions to improve real-life fashion photography"
        ]
      }
    `;

    const response = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [imagePart, { text: promptText }]
      },
      config: {
        temperature: 0.65,
        topK: 40,
        topP: 0.90,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prompts: {
              type: Type.ARRAY,
              items: { 
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING },
                  score: { type: Type.NUMBER }
                },
                required: ["text", "score"]
              }
            },
            detectedTexts: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            suggestions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["prompts", "suggestions"]
        }
      }
    }));

    const text = response.text;
    if (!text) throw new Error("AI không trả về nội dung.");

    try {
      return JSON.parse(text) as AnalysisResult;
    } catch (e) {
      console.error("JSON parse error:", text);
      throw new Error("Lỗi định dạng dữ liệu từ AI.");
    }

  } catch (error: any) {
    console.error("Lỗi khi gọi Gemini API:", error);
    throw error;
  }
};

