               <div className="flex gap-2">
                   {/* Translation buttons for DETECTED TEXT ONLY */}
                   <MotionButton
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                      onClick={() => handleBatchTranslateOverrides('en')}
