// Helper function to pause execution
export const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Generic retry wrapper for API calls
const retryOperation = async <T>(
  operation: () => Promise<T>, 
  retries: number = 3, 
  baseDelay: number = 2000
): Promise<T> => {
  let lastError: any;

  for (let i = 0; i < retries; i++) {
    try {
      return await operation();
    } catch (error: any) {
      lastError = error;
      const errorMessage = (error.message || JSON.stringify(error)).toLowerCase();

      // Identify retryable errors
      const isRateLimit = errorMessage.includes('429') || errorMessage.includes('resource exhausted') || errorMessage.includes('quota');
      const isNetwork = 
        errorMessage.includes('500') || 
        errorMessage.includes('503') || 
        errorMessage.includes('fetch failed') ||
        errorMessage.includes('network error') ||
        errorMessage.includes('overloaded');

      if ((!isRateLimit && !isNetwork) || i === retries - 1) {
        throw error;
      }

      // Exponential backoff
      const delay = isRateLimit 
        ? (baseDelay * Math.pow(2, i)) + 1000 
        : baseDelay * Math.pow(2, i);

      console.warn(`Gemini API retry attempt ${i + 1}/${retries} after ${delay}ms.`);
      await wait(delay);
    }
  }

  throw lastError;
};

export const decodeImagePrompt = async (base64Data: string, mimeType: string, count: number = 1): Promise<AnalysisResult> => {
  try {
    const ai = getClient();

    const imagePart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Data
      }
    };

    const mandatoryPrefix = "Create a highly realistic studio portrait of the Subject from the uploaded photo, ensuring Subject face is 99.99% identical to the reference.";

    const promptText = `
      You are a world-class Art Director, Professional Fashion Photographer, and Senior Reverse Prompt Engineer.
      GOAL: Analyze the image and decode it into a base "Absolute Replica" (Bản Sao Hoàn Hảo) prompt, and generate ${count} professional editorial variations.

      CRITICAL MANDATORY RULE:
      Every prompt you generate MUST start exactly with this sentence:
      "${mandatoryPrefix}"

      CRITICAL FOCUS 1: MASTER SUBJECT DESCRIPTION (IDENTITY & FASHION)
      Describe the subject in extreme detail. This description must be used consistently in all prompts to lock the identity:
      - CLOTHING: Describe exact garments, specific high-end materials (e.g., iridescent silk, heavy-weight raw denim, fine Italian lace, structured leather), and intricate textures.
      - ACCESSORIES & JEWELRY: Detail every accessory (earrings, necklaces, watches, belts, designer eyewear).
      - HAIR & BEAUTY: Precise hairstyle description, hair texture, and editorial makeup style (e.g., soft glam, avant-garde, matte finish).
      - IDENTITY: Lock the bone structure and facial characteristics for a perfect match.

      CRITICAL FOCUS 2: PROFESSIONAL PHOTOGRAPHY VARIATIONS
      For the variations, you MUST use expert photography terminology to create diverse, high-end looks.
      - VARIED POSES: High-fashion editorial poses, sitting, walking, dynamic movement, or relaxed natural stances.
      - DIVERSE CAMERA ANGLES: Low-angle (hero shot), high-angle, Dutch angle, bird's eye view, side profile, or 3/4 view.
      - SHOT DISTANCE & FRAMING: Close-up portraits, medium shots, full-body shots (showing the entire outfit and shoes), and wide-angle shots showing the subject in a professional studio or environmental context.
      - LIGHTING: Cinematic lighting, Rembrandt lighting, softbox diffusion, dramatic shadows, or rim lighting.

      CRITICAL FOCUS 3: TEXT & TYPOGRAPHY
      If the image contains text, identify exact words, font, color, and size. 
      In variations, keep the SAME text but reposition it logically (e.g., vertically on the side, as a footer, or integrated into the background) to complement the new framing and composition.

      VARIATION DIRECTION: 
      - THE SUBJECT (CLOTHES, HAIR, FACE) MUST NEVER CHANGE.
      - ONLY VARY the camera setup, pose, distance, and design layout.

      OUTPUT FORMAT (JSON ONLY)
      {
        "prompts": [
          { "text": "${mandatoryPrefix} [Absolute Replica: Detailed Subject + Original Typography + Original Pose/Framing]", "score": 10 },
          { "text": "${mandatoryPrefix} [Variation: Detailed Subject + Repositioned Typography + Full-body wide shot with low angle + High-fashion pose]", "score": 10 }
        ],
        "detectedTexts": ["Exact words found in image"],
        "suggestions": ["3 expert photography tips for this specific subject/style"]
      }
    `;

    const response = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [imagePart, { text: promptText }]
      },
      config: {
        temperature: 0.5,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prompts: {
              type: Type.ARRAY,
              items: { 
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING },
                  score: { type: Type.NUMBER }
                },
                required: ["text", "score"]
              }
            },
            detectedTexts: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            suggestions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["prompts", "suggestions"]
        }
      }
    }));

    const text = response.text;
    if (!text) throw new Error("AI không trả về nội dung.");

    try {
      return JSON.parse(text) as AnalysisResult;
    } catch (e) {
      throw new Error("Lỗi định dạng dữ liệu từ AI.");
    }

  } catch (error: any) {
    console.error("Lỗi khi gọi Gemini API:", error);
    throw error;
  }
};

