// Added React import to support React.FC, React.WheelEvent, and React.MouseEvent
import React, { useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface ImageInspectorProps {
  src: string;
  onReset?: () => void;
}

export const ImageInspector: React.FC<ImageInspectorProps> = ({ src, onReset }) => {
  const [scale, setScale] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [showControls, setShowControls] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const MotionDiv = motion.div as any;

  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.2 : 0.2;
    const newScale = Math.min(Math.max(1, scale + delta), 5);
    setScale(newScale);

    // If zooming back to 1, reset position
    if (newScale === 1) {
      setPosition({ x: 0, y: 0 });
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (scale === 1) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || scale === 1) return;
    setPosition({
      x: e.clientX - dragStart.x,
      y: e.clientY - dragStart.y
    });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const resetView = () => {
    setScale(1);
    setPosition({ x: 0, y: 0 });
  };

  return (
    <div 
      className="relative w-full max-w-2xl mx-auto bg-white rounded-kawaii p-1.5 shadow-2xl border-4 border-white overflow-hidden group"
      onMouseEnter={() => setShowControls(true)}
      onMouseLeave={() => {
        setShowControls(false);
        handleMouseUp();
      }}
    >
      {/* Animated Kawaii Gradient Border Wrapper */}
      <div className="relative p-2 rounded-kawaii-inner overflow-hidden">
        {/* The subtle animated background for the border */}
        <div 
          className="absolute inset-0 bg-gradient-to-r from-pink-200 via-purple-200 to-blue-200 opacity-40 group-hover:opacity-100 group-hover:animate-gradient-x transition-opacity duration-700"
          style={{ backgroundSize: '200% 200%' }}
        />

        {/* Main Image Viewport */}
        <div 
          ref={containerRef}
          className={`relative aspect-[4/5] md:aspect-square rounded-[1.8rem] overflow-hidden bg-gray-50 shadow-inner cursor-all-scroll z-10
            ${scale > 1 ? 'cursor-grabbing' : 'cursor-zoom-in'}`}
          onWheel={handleWheel}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
        >
          <MotionDiv
            animate={{ 
              scale: scale,
              x: position.x,
              y: position.y
            }}
            transition={isDragging ? { type: 'tween', duration: 0 } : { type: 'spring', stiffness: 300, damping: 30 }}
            className="w-full h-full"
          >
            <img 
              src={src} 
              alt="Inspection" 
              className="w-full h-full object-cover pointer-events-none select-none"
              draggable={false}
            />
          </MotionDiv>

          {/* Overlay Instructions */}
          <AnimatePresence>
            {showControls && scale === 1 && (
              <motion.div 
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="absolute inset-0 bg-black/10 pointer-events-none flex flex-col items-center justify-center text-white p-6 text-center z-20"
              >
                <div className="bg-white/30 backdrop-blur-md px-5 py-2.5 rounded-full border border-white/40 text-[10px] font-black uppercase tracking-widest flex items-center gap-2 shadow-sm">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0zM10 7v3m0 0v3m0-3h3m-3 0H7" />
                  </svg>
                  Cuộn để soi chi tiết ✨
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* Scale Badge */}
          {scale > 1 && (
            <div className="absolute top-5 left-5 bg-pink-500/90 backdrop-blur-sm text-white px-3 py-1 rounded-full text-[10px] font-black shadow-lg border-2 border-white z-30">
              {scale.toFixed(1)}x
            </div>
          )}

          {/* Action Buttons */}
          <div className="absolute top-5 right-5 flex flex-col gap-3 z-30">
            {onReset && (
              <button 
                onClick={(e) => { e.stopPropagation(); onReset(); }}
                className="bg-white/90 hover:bg-red-50 text-gray-400 hover:text-red-500 p-2.5 rounded-full shadow-lg backdrop-blur-sm transition-all transform hover:rotate-90 border-2 border-white"
                title="Xóa ảnh"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
