import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { AnalysisResult, PromptItem } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key chưa được cấu hình trong hệ thống. Vui lòng kiểm tra biến môi trường.");
  }
  return new GoogleGenAI({ apiKey });
};

// Helper function to pause execution
export const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Generic retry wrapper for API calls
const retryOperation = async <T>(
  operation: () => Promise<T>, 
  retries: number = 3, 
  baseDelay: number = 2000
): Promise<T> => {
  let lastError: any;

  for (let i = 0; i < retries; i++) {
    try {
      return await operation();
    } catch (error: any) {
      lastError = error;
      const errorMessage = (error.message || JSON.stringify(error)).toLowerCase();

      const isRateLimit = errorMessage.includes('429') || errorMessage.includes('resource exhausted') || errorMessage.includes('quota');
      const isNetwork = 
        errorMessage.includes('500') || 
        errorMessage.includes('503') || 
        errorMessage.includes('fetch failed') ||
        errorMessage.includes('network error') ||
        errorMessage.includes('overloaded');

      if ((!isRateLimit && !isNetwork) || i === retries - 1) {
        throw error;
      }

      const delay = isRateLimit 
        ? (baseDelay * Math.pow(2, i)) + 1000 
        : baseDelay * Math.pow(2, i);

      console.warn(`Gemini API retry attempt ${i + 1}/${retries} after ${delay}ms.`);
      await wait(delay);
    }
  }

  throw lastError;
};

export const decodeImagePrompt = async (base64Data: string, mimeType: string, count: number = 1): Promise<AnalysisResult> => {
  try {
    const ai = getClient();

    const imagePart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Data
      }
    };

    const mandatoryPrefix = "Create a highly realistic studio portrait of the Subject from the uploaded photo, ensuring Subject face is 99.99% identical to the reference.";

    const promptText = `
      You are an Elite Reverse Prompt Engineer and Professional Fashion Photographer.
      GOAL: Decode this image into an "Absolute Replica" prompt and generate ${count} logically sound high-end variations.

      CRITICAL MANDATORY RULE:
      Every prompt MUST start with: "${mandatoryPrefix}"

      STEP 1: FORENSIC ASSET AUDIT (LOCKED ASSETS)
      Analyze the subject's physical and style attributes. These MUST be explicitly described in every prompt to maintain 100% identity consistency:
      - FACE & HAIR: Micro-describe facial structure, skin texture, and exact hairstyle (length, texture, specific highlights/colors, styling).
      - FASHION & MATERIALS: Identify exact garments, fabrics (silk, tweed, neoprene), stitching, and fit.
      - ACCESSORIES: Jewelry, glasses, or props.

      STEP 2: LOGICAL VARIATION FRAMEWORK
      Distribute the ${count} variations across these logical photography tiers to ensure a professional portfolio look:

      1. THE REPLICA (Prompt 1): Exact match of the original image pose, framing, and lighting.
      2. THE CLOSE-UP (Portrait): Focus on facial details, expression, and jewelry. Use 85mm or 100mm lens specs.
      3. THE MEDIUM SHOT (Waist-up): Show the torso and upper-body gestures. Focus on fabric textures and upper fashion details. Use 50mm lens specs.
      4. THE FULL BODY (Editorial): Show the complete silhouette including footwear. Focus on posture and environmental interaction. Use 35mm lens specs.
      5. THE ACTION/DYNAMIC: Add subtle motion (hair flying, walking, leaning) while keeping the face perfectly sharp.

      CRITICAL LOGIC RULES:
      - POSES: Must be humanly natural and high-fashion editorial. No "broken-neck" or physically impossible poses.
      - CAMERA LOGIC: Adjust lighting (Rim lighting, Rembrandt, Butterfly) and f-stop (f/1.8 for close-ups, f/8 for full-body) according to the shot type.
      - TYPOGRAPHY: Describe existing text at the end of the prompt. Vary its placement (e.g., "overlayed on top", "integrated into the background", "magazine cover style") to fit the new framing.

      OUTPUT FORMAT (JSON ONLY)
      {
        "prompts": [
          { "text": "${mandatoryPrefix} [Forensic Style Audit] + [Replica Framing/Pose] + [Typography]", "score": 10 },
          { "text": "${mandatoryPrefix} [Forensic Style Audit] + [New Logical Framing/Pose Variation] + [Typography Adjustment]", "score": 10 }
        ],
        "detectedTexts": ["Exact words found in image"],
        "suggestions": ["3 expert tips for achieving the best results with these variations"]
      }
    `;

    const response = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [imagePart, { text: promptText }]
      },
      config: {
        temperature: 0.4,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prompts: {
              type: Type.ARRAY,
              items: { 
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING },
                  score: { type: Type.NUMBER }
                },
                required: ["text", "score"]
              }
            },
            detectedTexts: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            suggestions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["prompts", "suggestions"]
        }
      }
    }));

    const text = response.text;
    if (!text) throw new Error("AI không trả về nội dung.");

    try {
      return JSON.parse(text) as AnalysisResult;
    } catch (e) {
      throw new Error("Lỗi định dạng dữ liệu từ AI.");
    }

  } catch (error: any) {
    console.error("Lỗi khi gọi Gemini API:", error);
    throw error;
  }
};

export const optimizePrompt = async (originalPrompt: string): Promise<PromptItem> => {
  try {
    const ai = getClient();
    const mandatoryPrefix = "Create a highly realistic studio portrait of the Subject from the uploaded photo, ensuring Subject face is 99.99% identical to the reference.";

    const promptText = `
      You are a Professional Photography & Fashion Consultant.
      TASK: Enhance the technical depth of this prompt while maintaining 100% consistency for the Subject's hair, clothes, and accessories.

      RULES:
      1. MANDATORY START: "${mandatoryPrefix}"
      2. Polish the lighting (cinematic, global illumination) and camera specs (depth of field, chromatic aberration).
      3. Use luxury fashion terminology for fabric descriptions.
      4. Ensure the pose is described with anatomical accuracy and professional modeling intent.

      INPUT: "${originalPrompt}"
      OUTPUT JSON: { "text": "...", "score": 10 }
    `;

    const response = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
         parts: [{ text: promptText }]
      },
      config: {
        temperature: 0.7,
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            text: { type: Type.STRING },
            score: { type: Type.NUMBER }
          },
          required: ["text", "score"]
        }
      }
    }));

    const text = response.text;
    if (!text) throw new Error("No response");
    return JSON.parse(text) as PromptItem;
  } catch (error: any) {
     console.error("Optimize error:", error);
     throw new Error("Không thể tối ưu hóa prompt lúc này.");
  }
};

export const translateText = async (text: string, targetLang: 'en' | 'vi'): Promise<string> => {
  try {
    const ai = getClient();
    const promptText = `Translate to ${targetLang === 'en' ? 'English' : 'Vietnamese'}. Keep technical photography, fabric names, and the mandatory prefix in English. Text: "${text}"`;

    const response = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
         parts: [{ text: promptText }]
      },
      config: {
        temperature: 0.3,
        responseMimeType: 'text/plain'
      }
    }));

    return response.text?.trim() || text;
  } catch (error) {
    console.error("Translation error:", error);
    throw error;
  }
};

