import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { AnalysisResult, PromptItem } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key chưa được cấu hình trong hệ thống. Vui lòng kiểm tra biến môi trường.");
  }
  return new GoogleGenAI({ apiKey });
};

// Helper function to pause execution
export const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Generic retry wrapper for API calls
const retryOperation = async <T>(
  operation: () => Promise<T>, 
  retries: number = 3, 
  baseDelay: number = 2000
): Promise<T> => {
  let lastError: any;

  for (let i = 0; i < retries; i++) {
    try {
      return await operation();
    } catch (error: any) {
      lastError = error;
      const errorMessage = (error.message || JSON.stringify(error)).toLowerCase();

      const isRateLimit = errorMessage.includes('429') || errorMessage.includes('resource exhausted') || errorMessage.includes('quota');
      const isNetwork = 
        errorMessage.includes('500') || 
        errorMessage.includes('503') || 
        errorMessage.includes('fetch failed') ||
        errorMessage.includes('network error') ||
        errorMessage.includes('overloaded');

      if ((!isRateLimit && !isNetwork) || i === retries - 1) {
        throw error;
      }

      const delay = isRateLimit 
        ? (baseDelay * Math.pow(2, i)) + 1000 
        : baseDelay * Math.pow(2, i);

      console.warn(`Gemini API retry attempt ${i + 1}/${retries} after ${delay}ms.`);
      await wait(delay);
    }
  }

  throw lastError;
};

export const decodeImagePrompt = async (base64Data: string, mimeType: string, count: number = 1): Promise<AnalysisResult> => {
  try {
    const ai = getClient();

    const imagePart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Data
      }
    };

    const mandatoryPrefix = "Create a highly realistic studio portrait of the Subject from the uploaded photo, ensuring Subject face is 99.99% identical to the reference.";

    const promptText = `
      You are an Elite Reverse Prompt Engineer and Professional Fashion Photographer.
      GOAL: Analyze the uploaded image and generate ${count} prompts that maintain 100% character and environmental consistency.

      CRITICAL MANDATORY RULE:
      Every prompt MUST start with: "${mandatoryPrefix}"

      STEP 1: DEEP ASSET AUDIT (LOCKED ASSETS - DO NOT ALTER)
      Perform a forensic analysis of the following elements and keep them IDENTICAL in every generated variation:
      - HAIR: Exact style, precise color/tones, texture (silky, wavy, frizzy), and highlights.
      - CLOTHING: Exact garment types, specific fabric textures (silk, leather, knit, denim), patterns, and color palette.
      - JEWELRY & ACCESSORIES: Identify every ring, earring, necklace, glasses, or hat. Describe their material (gold, silver, pearl) and exact position.
      - ENVIRONMENT/BACKGROUND: Analyze the lighting (warm, cool, neon), the setting (indoor, urban, studio), and background colors/props.

      STEP 2: LOGICAL PHOTOGRAPHY VARIATIONS (ALTER ONLY THESE)
      Generate ${count} variations by changing ONLY the camera framing and character pose, while using the audited assets from Step 1:

      1. THE REPLICA: Mirror the original pose and framing exactly.
      2. THE MACRO PORTRAIT: Extreme close-up focusing on eyes and face details. (85mm lens, f/1.8).
      3. THE WAIST-UP EDITORIAL: Subject in the same outfit, showing upper body gestures. (50mm lens).
      4. THE FULL-BODY SILHOUETTE: Subject in the same outfit, full pose interaction with the original background. (35mm lens).
      5. THE DYNAMIC MOVEMENT: Subject in the same outfit with a subtle action (hair swaying, walking) while maintaining face clarity.

      CRITICAL LOGIC:
      - Do NOT hallucinate new clothes or different hairstyles.
      - If text is present, preserve it or adapt its placement logically for the new framing.

      OUTPUT FORMAT (JSON ONLY)
      {
        "prompts": [
          { "text": "${mandatoryPrefix} [Audited Character Assets] + [Camera/Pose Variation] + [Environment] + [Typography]", "score": 10 }
        ],
        "detectedTexts": ["Exact words found in image"],
        "suggestions": ["3 tips for maintaining identity consistency in AI generation"]
      }
    `;

    const response = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [imagePart, { text: promptText }]
      },
      config: {
        temperature: 0.2, // Lower temperature for higher consistency
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prompts: {
              type: Type.ARRAY,
              items: { 
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING },
                  score: { type: Type.NUMBER }
                },
                required: ["text", "score"]
              }
            },
            detectedTexts: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            suggestions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["prompts", "suggestions"]
        }
      }
    }));

    const text = response.text;
    if (!text) throw new Error("AI không trả về nội dung.");

    try {
      return JSON.parse(text) as AnalysisResult;
    } catch (e) {
      throw new Error("Lỗi định dạng dữ liệu từ AI.");
    }

  } catch (error: any) {
    console.error("Lỗi khi gọi Gemini API:", error);
    throw error;
  }
};

