import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { AnalysisResult, PromptItem } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key chưa được cấu hình trong hệ thống. Vui lòng kiểm tra biến môi trường.");
  }
  return new GoogleGenAI({ apiKey });
};

// Helper function to pause execution
export const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Generic retry wrapper for API calls with faster backoff
const retryOperation = async <T>(
  operation: () => Promise<T>, 
  retries: number = 3, 
  baseDelay: number = 1000
): Promise<T> => {
  let lastError: any;

  for (let i = 0; i < retries; i++) {
    try {
      return await operation();
    } catch (error: any) {
      lastError = error;
      const errorMessage = (error.message || JSON.stringify(error)).toLowerCase();

      const isRateLimit = errorMessage.includes('429') || errorMessage.includes('resource exhausted') || errorMessage.includes('quota');
      const isNetwork = 
        errorMessage.includes('500') || 
        errorMessage.includes('503') || 
        errorMessage.includes('fetch failed') ||
        errorMessage.includes('network error') ||
        errorMessage.includes('overloaded');

      if ((!isRateLimit && !isNetwork) || i === retries - 1) {
        throw error;
      }

      const delay = isRateLimit 
        ? (baseDelay * Math.pow(2, i)) + 500 
        : baseDelay * Math.pow(2, i);

      await wait(delay);
    }
  }

  throw lastError;
};

export const decodeImagePrompt = async (base64Data: string, mimeType: string, count: number = 1): Promise<AnalysisResult> => {
  try {
    const ai = getClient();

    const imagePart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Data
      }
    };

    const mandatoryPrefix = "Create a highly realistic studio portrait of the Subject from the uploaded photo, ensuring Subject face is 99.99% identical to the reference.";

    const promptText = `
      You are an Elite Reverse Prompt Engineer and Fashion Concept Creator.
      GOAL: Analyze the subject's identity (FACE) and generate ${count} NEW high-end fashion concepts.

      CRITICAL MANDATORY RULE: Start every prompt with: "${mandatoryPrefix}"

      IDENTITY PROTOCOL (FACE ONLY):
      - LOCK: Facial features, bone structure, eye shape, and unique identity markers from the reference image.
      - IGNORE: Do NOT copy the clothing, hairstyle, or accessories from the uploaded photo. These are placeholders.

      CONCEPT GENERATION (FASHION & HAIR FREEDOM):
      For each prompt, design a COMPLETELY NEW look that fits a high-fashion editorial:
      1. HAIRSTYLE: Create new styles (e.g., sleek ponytail, messy waves, avant-garde braids, platinum blonde bob) that complement the face.
      2. CLOTHING: Design couture outfits with specific materials (e.g., iridescent vinyl, heavy silk velvet, architectural wool). Focus on intricate SEWING details and modern silhouettes.
      3. ACCESSORIES: Suggest luxury jewelry or eyewear that was NOT in the original image.
      4. ENVIRONMENT & LIGHTING: Masterclass cinematic lighting (volumetric, rim-lit, neon accents).

      PROMPT VARIATIONS:
      - VARIATION 1: High-Fashion Editorial (Avant-garde).
      - VARIATION 2: Luxury Streetwear (Cyberpunk/Urban).
      - VARIATION 3: Red Carpet Elegance (Classic Luxury).
      - VARIATION 4: Minimalism (Quiet Luxury, focus on fabric texture).
      - VARIATION 5: Cinematic Action (Dynamic movement and lighting).

      STRICT: The face must be the ONLY thing kept from the reference. Everything else must be an upgrade or a creative departure.
    `;

    const response = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-2.5-flash-lite',
      contents: {
        parts: [imagePart, { text: promptText }]
      },
      config: {
        temperature: 0.7, // Increased temperature for more creative fashion variety
        thinkingConfig: { thinkingBudget: 0 },
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prompts: {
              type: Type.ARRAY,
              items: { 
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING },
                  score: { type: Type.NUMBER }
                },
                required: ["text", "score"]
              }
            },
            detectedTexts: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            suggestions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["prompts", "suggestions"]
        }
      }
    }));

    const text = response.text;
    if (!text) throw new Error("AI không trả về nội dung.");
    return JSON.parse(text) as AnalysisResult;
  } catch (error: any) {
    console.error("Lỗi Gemini API:", error);
    throw error;
  }
};

