export const decodeImagePrompt = async (base64Data: string, mimeType: string, count: number = 1): Promise<AnalysisResult> => {
  try {
    const ai = getClient();

    const imagePart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Data
      }
    };

    const mandatoryPrefix = "Create a highly realistic studio portrait of the Subject from the uploaded photo, ensuring Subject face is 99.99% identical to the reference. Reference ONLY the Subject's face (do not reference hairstyle), and create a body physique that is balanced and proportional to the Subject's face. ";

    const promptText = `
      You are an Elite Reverse Prompt Engineer specialized in High-End Bridal & Editorial Fashion.
      GOAL: Analyze the subject's identity and generate ${count} LUXURY BRIDAL variations based on a romantic garden theme.

      CRITICAL MANDATORY RULE: Every prompt must start exactly with: "${mandatoryPrefix}"

      IDENTITY PROTOCOL:
      - Preserve 100% of facial bone structure, eyes, and unique features.
      - Ignore the clothing and hair in the original photo.

      OPTIMIZATION CONCEPT (The "Romantic Bridal Garden" Framework):
      Integrate these 10 specific elements into your prompt generation logic:
      1. Bridal portrait: Focus on elegance and wedding-day radiance.
      2. Garden wedding: Use dreamlike outdoor settings with lush greenery.
      3. Ethereal gown: Describe gowns that look light, airy, and magical.
      4. Off-the-shoulder dress: Use this silhouette for romantic appeal.
      5. Organza fabric: Describe the translucent, crisp texture of the dress.
      6. Sheer sleeves: Add delicate, transparent sleeve details.
      7. Floral background: Surround the subject with soft, seasonal flowers.
      8. Natural lighting: Use golden hour or soft diffused sunbeams.
      9. Romantic pose: Suggest gentle, sophisticated posing.
      10. Elegant jewelry: Detail high-end pearls or diamond accents.

      VARIATION STRATEGY:
      Generate ${count} variations. Each should be a unique "High-Fashion Bridal Editorial" prompt.
      Incorporate different combinations of the fabrics and lighting mentioned above.
      Make the descriptions highly technical (e.g., "bias-cut organza", "volumetric sun-rays", "macro floral bokeh").
    `;

    const response = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [imagePart, { text: promptText }]
      },
      config: {
        temperature: 0.75,
        thinkingConfig: { thinkingBudget: 0 },
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prompts: {
              type: Type.ARRAY,
              items: { 
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING },
                  score: { type: Type.NUMBER }
                },
                required: ["text", "score"]
              }
            },
            suggestions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["prompts", "suggestions"]
        }
      }
    }));

    const text = response.text;
    if (!text) throw new Error("AI không trả về nội dung.");
    return JSON.parse(text) as AnalysisResult;
  } catch (error: any) {
    console.error("Lỗi Gemini API:", error);
    throw error;
  }
};

