import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { AnalysisResult, PromptItem } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key chưa được cấu hình trong hệ thống. Vui lòng kiểm tra biến môi trường.");
  }
  return new GoogleGenAI({ apiKey });
};

// Helper function to pause execution
export const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Generic retry wrapper for API calls with faster backoff
const retryOperation = async <T>(
  operation: () => Promise<T>, 
  retries: number = 3, 
  baseDelay: number = 1000
): Promise<T> => {
  let lastError: any;

  for (let i = 0; i < retries; i++) {
    try {
      return await operation();
    } catch (error: any) {
      lastError = error;
      const errorMessage = (error.message || JSON.stringify(error)).toLowerCase();

      const isRateLimit = errorMessage.includes('429') || errorMessage.includes('resource exhausted') || errorMessage.includes('quota');
      const isNetwork = 
        errorMessage.includes('500') || 
        errorMessage.includes('503') || 
        errorMessage.includes('fetch failed') || 
        errorMessage.includes('network error') ||
        errorMessage.includes('overloaded');

      if ((!isRateLimit && !isNetwork) || i === retries - 1) {
        throw error;
      }

      const delay = isRateLimit 
        ? (baseDelay * Math.pow(2, i)) + 500 
        : baseDelay * Math.pow(2, i);

      await wait(delay);
    }
  }

  throw lastError;
};

export const decodeImagePrompt = async (base64Data: string, mimeType: string, count: number = 1): Promise<AnalysisResult> => {
  try {
    const ai = getClient();

    const imagePart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Data
      }
    };

    const promptText = `
      You are a World-Class Fashion Photographer and Art Director (vogue/cinematic style).
      GOAL: Analyze the uploaded image to create ${count} highly detailed prompts that capture the essence of the original masterpiece.

      PHASE 1: MICROSCOPIC ANALYSIS (The DNA of the Image)
      Analyze the image with extreme precision, focusing on these specific layers:
      1. **CONTEXT & ENVIRONMENT**: Don't just say "indoors". Describe the architecture, furniture style (e.g., Victorian, Mid-century), time of day, weather, and background blur (bokeh).
      2. **FASHION & TEXTILES**: Analyze fabric physics. Is it "sheer silk organza", "heavyweight knitted wool", or "distressed denim"? Mention folds, drape, and texture.
      3. **JEWELRY & ACCESSORIES**: Detail every accessory. Gold carat, gemstone type (diamond, sapphire), cut (emerald, brilliant), watch brands/styles, glasses frames.
      4. **COLOR PALETTE**: Identify the dominant color grading (e.g., "Teal and Orange", "Pastel Pink", "Moody Noir").
      5. **COMPOSITION & CAMERA**: Focal length (e.g., 85mm, 35mm wide), aperture (f/1.8), camera angle (Dutch angle, low angle), and framing (Rule of thirds).
      6. **IDENTITY**: Exact face features, skin texture, makeup style, and hair details.

      PHASE 2: PROMPT GENERATION

      **Prompt 1: THE MASTER REPLICA**
      - Describe the original image using the detailed analysis above.
      - **CRITICAL**: You must explicitly describe the material of the outfit (e.g., "shimmering satin"), the specific jewelry, and the lighting setup.
      - **Start with**: "Masterpiece shot. [Subject & Detailed Outfit]... ensuring subject face is 99.99% identical to the reference."

      **Prompt 2 to ${count}: STYLISTIC VARIATIONS**
      - **LOCK**: The Subject (Face/Body), Outfit (Materials/Textures), and Accessories MUST BE IDENTICAL to Prompt 1.
      - **CHANGE**: The Context, Pose, and Camera Angle.
      - **INSTRUCTION**: Even in variations, do not summarize the outfit. Re-state the detailed fabric and accessory descriptions to ensure the AI generator doesn't lose detail.

      **Structure for Prompts**:
      "[Artistic Style/Lens Info]. [Subject Description with EXTREME detail on Fabric/Jewelry]. [Action/Pose] in [Detailed Context/Environment]. [Lighting & Color Grading]. [Composition]. ensuring subject face is 99.99% identical to the reference."
    `;

    const response = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [imagePart, { text: promptText }]
      },
      config: {
        temperature: 0.75, // Increased slightly for more creative variations
        thinkingConfig: { thinkingBudget: 0 },
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prompts: {
              type: Type.ARRAY,
              items: { 
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING },
                  score: { type: Type.NUMBER }
                },
                required: ["text", "score"]
              }
            },
            suggestions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            detectedTexts: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["prompts", "suggestions"]
        }
      }
    }));

    const text = response.text;
    if (!text) throw new Error("AI không trả về nội dung.");
    return JSON.parse(text) as AnalysisResult;
  } catch (error: any) {
    console.error("Lỗi Gemini API:", error);
    throw error;
  }
};

export const optimizePrompt = async (originalPrompt: string): Promise<PromptItem> => {
  try {
    const ai = getClient();
    const promptText = `
      Professional Prompt Optimizer.
      GOAL: Upgrade this prompt to "Award-Winning Photography" level.

      INSTRUCTIONS:
      1.  **Preserve Core Elements**: Do NOT change the description of the person or clothes.
      2.  **Enhance Aesthetics**: Add professional keywords for lighting (e.g., volumetric lighting, rim light), texture (e.g., 8k, highly detailed), and camera gear.
      3.  **Conciseness**: Remove redundant words, focus on visual impact.
      4.  Input: "${originalPrompt}"
    `;

    const response = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
         parts: [{ text: promptText }]
      },
      config: {
        temperature: 0.5,
        thinkingConfig: { thinkingBudget: 0 },
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            text: { type: Type.STRING },
            score: { type: Type.NUMBER }
          },
          required: ["text", "score"]
        }
      }
    }));

    const text = response.text;
    if (!text) throw new Error("No response");
    return JSON.parse(text) as PromptItem;
  } catch (error: any) {
     throw new Error("Không thể tối ưu hóa prompt lúc này.");
  }
};

export const translateText = async (text: string, targetLang: 'en' | 'vi'): Promise<string> => {
  try {
    const ai = getClient();
    const promptText = `
      Task: Translate the following text to ${targetLang === 'en' ? 'English' : 'Vietnamese'}.

      Constraints:
      1. Keep fashion technical terms (e.g., organza, ethereal, sheer, bokeh, shot on 35mm) in English.
      2. Keep camera terms and specific identity prefixes in English.
      3. **CRITICAL**: Return ONLY the translated text directly. Do NOT include any introductory phrases like "Here is the translation" or "Dưới đây là bản dịch".

      Text to translate: "${text}"
    `;

    const response = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
         parts: [{ text: promptText }]
      },
      config: {
        temperature: 0.1,
        thinkingConfig: { thinkingBudget: 0 }
      }
    }));

    return response.text?.trim() || text;
  } catch (error) {
    return text;
  }
};

