import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { AnalysisResult, PromptItem } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key chưa được cấu hình trong hệ thống. Vui lòng kiểm tra biến môi trường.");
  }
  return new GoogleGenAI({ apiKey });
};

// Helper function to pause execution
export const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Generic retry wrapper for API calls with faster backoff
const retryOperation = async <T>(
  operation: () => Promise<T>, 
  retries: number = 3, 
  baseDelay: number = 1000
): Promise<T> => {
  let lastError: any;

  for (let i = 0; i < retries; i++) {
    try {
      return await operation();
    } catch (error: any) {
      lastError = error;
      const errorMessage = (error.message || JSON.stringify(error)).toLowerCase();

      const isRateLimit = errorMessage.includes('429') || errorMessage.includes('resource exhausted') || errorMessage.includes('quota');
      const isNetwork = 
        errorMessage.includes('500') || 
        errorMessage.includes('503') || 
        errorMessage.includes('fetch failed') || 
        errorMessage.includes('network error') ||
        errorMessage.includes('overloaded');

      if ((!isRateLimit && !isNetwork) || i === retries - 1) {
        throw error;
      }

      const delay = isRateLimit 
        ? (baseDelay * Math.pow(2, i)) + 500 
        : baseDelay * Math.pow(2, i);

      await wait(delay);
    }
  }

  throw lastError;
};

export const decodeImagePrompt = async (base64Data: string, mimeType: string, count: number = 1): Promise<AnalysisResult> => {
  try {
    const ai = getClient();

    const imagePart = {
      inlineData: {
        mimeType: mimeType,
        data: base64Data
      }
    };

    const promptText = `
      You are an Elite AI Art Director & Cinematic Storyboard Artist.
      GOAL: Analyze the uploaded image to create ${count} highly detailed, narrative-style prompts.

      **STYLE REFERENCE (MUST EMULATE THIS WRITING STYLE & DEPTH):**
      "Create a portrait of a young woman with a fresh, delicate face and naturally smooth, radiant skin. She wears light makeup in soft pink–peach tones... She is wearing a deep red vintage-style áo dài. The mid-length sleeves are made of sheer chiffon with a subtle flare, while the main body is crafted from lightweight linen... She is sitting on a low wooden step in an outdoor Vietnamese Lunar New Year flower market... Outdoor setting with natural late-afternoon light... The image is captured with a professional mirrorless or DSLR camera, using an 85mm lens at f/1.8 aperture..."

      **INSTRUCTIONS FOR PROMPT GENERATION:**
      Do NOT write short lists. Write full, descriptive paragraphs following this specific flow:

      1.  **SUBJECT & VISAGE**: Start with "Create a [type of shot] of...". Describe face, skin texture, makeup tones, hair volume/style/strands in detail.
      2.  **OUTFIT & TEXTILES**: Describe the outfit with high attention to materials (e.g., sheer chiffon, lightweight linen, heavy wool, satin), cuts, sleeves, and accessories.
      3.  **POSE & ACTION**: Describe how they sit/stand, hand placement, and interaction with props.
      4.  **ENVIRONMENT (Detailed)**: Describe the setting vividly. Mention specific background elements, blurs, and atmosphere.
      5.  **LIGHTING & MOOD**: Describe the time of day, light direction (diagonal, rim light), and emotional tone (nostalgic, peaceful).
      6.  **TECHNICAL SPECS**: Mention camera gear (85mm, f/1.8), depth of field, bokeh quality, and color palette.

      **PHASE 1: IMAGE ANALYSIS**
      Extract these details from the uploaded image.

      **PHASE 2: PROMPT CREATION**

      **Prompt 1: THE MASTER REPLICA**
      - Recreate the uploaded image exactly using the "Reference Style" narrative structure above.
      - Ensure the facial features and outfit materials are described with 100% accuracy.

      **Prompt 2 to ${count}: NARRATIVE VARIATIONS**
      - **LOCK**: Subject Identity (Face/Hair) and Outfit (Materials) MUST be identical to Prompt 1.
      - **CHANGE**: The Context/Background and Pose.
      - Write these as fully fleshed-out scenes (e.g., "She is walking down a rainy neon street...", "She is reading a book in a sunlit library..."), maintaining the same high level of detail for lighting and texture.

      Output JSON format with 'prompts' (text, score) and 'suggestions' and 'detectedTexts'.
    `;

    const response = await retryOperation<GenerateContentResponse>(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [imagePart, { text: promptText }]
      },
      config: {
        temperature: 0.7,
        thinkingConfig: { thinkingBudget: 0 },
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prompts: {
              type: Type.ARRAY,
              items: { 
                type: Type.OBJECT,
                properties: {
                  text: { type: Type.STRING },
                  score: { type: Type.NUMBER }
                },
                required: ["text", "score"]
              }
            },
            suggestions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            detectedTexts: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["prompts", "suggestions"]
        }
      }
    }));

    const text = response.text;
    if (!text) throw new Error("AI không trả về nội dung.");
    return JSON.parse(text) as AnalysisResult;
  } catch (error: any) {
    console.error("Lỗi Gemini API:", error);
    throw error;
  }
};

